```python
def custom_sort(lst):
    if not lst:
        return lst

    # Separate numbers, strings, and nested lists
    numbers = []
    strings = []
    nested_lists = []

    for item in lst:
        if isinstance(item, (int, float)):
            numbers.append(item)
        elif isinstance(item, str):
            strings.append(item)
        elif isinstance(item, list):
            nested_lists.append(item)

    # Sort numbers in descending order
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if numbers[i] < numbers[j]:
                numbers[i], numbers[j] = numbers[j], numbers[i]

    # Sort strings in alphabetical order
    for i in range(len(strings)):
        for j in range(i + 1, len(strings)):
            if strings[i] > strings[j]:
                strings[i], strings[j] = strings[j], strings[i]

    # Sort nested lists based on the sum of their elements
    for i in range(len(nested_lists)):
        for j in range(i + 1, len(nested_lists)):
            if sum(nested_lists[i]) < sum(nested_lists[j]):
                nested_lists[i], nested_lists[j] = nested_lists[j], nested_lists[i]

    # Combine sorted lists
    return numbers + strings + nested_lists

# Example usage:
