```python
class DoublyLinkedListNode:
    def __init__(self, data):
        self.data = data
        self.next = None
        self.prev = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None

    def insert_after(self, node, data):
        if node is None:
            if self.head is None:
                self.head = DoublyLinkedListNode(data)
            else:
                raise ValueError("Node cannot be None unless the list is empty.")
        else:
            new_node = DoublyLinkedListNode(data)
            new_node.next = node.next
            new_node.prev = node
            if node.next:
                node.next.prev = new_node
            node.next = new_node

    def delete_node(self, node):
        if node is None:
            raise ValueError("Node to delete cannot be None.")
        if node.prev:
            node.prev.next = node.next
        if node.next:
            node.next.prev = node.prev
        if node == self.head:
            self.head = node.next
        node.next = node.prev = None

    def find_previous_node(self, data):
        current = self.head
        while current and current.next:
            if current.next.data == data:
                return current
            current = current.next
        return None

    def find_next_node(self, data):
        current = self.head
        while current:
            if current.data == data and current.next:
                return current.next
            current = current.next
        return None

    def find_last_node(self):
        current = self.head
        while current and current.next:
            current = current.next
        return current

    def reverse(self):
        current = self.head
        prev = None
        while current:
            next_node = current.next
            current.next = prev
            current.prev = next_node
            prev = current
            current = next_node
        self.head = prev

    def sort(self):
        if self.head is None or self.head.next is None:
            return
        current = self.head
        while current:
            next_node = current.next
            while next_node:
                if current.data > next_node.data:
                    current.data, next_node.data = next_node.data, current.data
                next_node = next_node.next
            current = current.next

    def merge_sorted(self, other):
        dummy = DoublyLinkedListNode(0)
        tail = dummy
        a, b = self.head, other.head
        while a and b:
            if a.data < b.data:
                tail.next = a
                a.prev = tail
                a = a.next
            else:
                tail.next = b
                b.prev = tail
                b = b.next
            tail = tail.next
        tail.next = a or b
        if tail.next:
            tail.next.prev = tail
        self.head = dummy.next
        if self.head:
            self.head.prev = None

    def remove_duplicates(self):
        current = self.head
        seen = set()
        while current:
            if current.data in seen:
                self.delete_node(current)
            else:
                seen.add(current.data)
            current = current.next

    def find_kth_from_end(self, k):
        fast = slow = self.head
        for _ in range(k):
            if fast is None:
                raise ValueError("k is larger than the list length.")
            fast = fast.next
        while fast:
            slow = slow.next
            fast = fast.next
        return slow

    def split_odd_even(self):
        odd_list = DoublyLinkedList()
        even_list = DoublyLinkedList()
        current = self.head
        index = 0
        while current:
            if index % 2 == 0:
                even_list.insert_after(even_list.find_last_node(), current.data)
            else:
                odd_list.insert_after(odd_list.find_last_node(), current.data)
            current = current.next
            index += 1
        return odd_list, even_list

    def find_median(self):
        if self.head is None:
            raise ValueError("List is empty.")
        length = 0
        current = self.head
        while current:
            length += 1
            current = current.next
        mid = length // 2
        current = self.head
        for _ in range(mid):
            current = current.next
        if length % 2 == 0:
            return (current.prev.data + current.data) / 2
        else:
            return current.data

    def rotate(self, positions):
        if self.head is None:
            return
        length = 0
        current = self.head
        while current:
            length += 1
            current = current.next
        positions %= length
        if positions == 0:
            return
        current = self.head
        for _ in range(positions):
            current = current.next
        new_head = current
        while current.next:
            current = current.next
        current.next = self.head
        self.head.prev = current
        self.head = new_head
        self.head.prev.next = None
        self.head.prev = None

# Example usage:
dll = DoublyLinkedList()
dll.insert_after(None, 3)
dll.insert_after(dll.head, 1)
dll.insert_after(dll.head.next, 4)
dll.insert_after(dll.head.next.next, 1)
dll.insert_after(dll.head.next.next.next, 5)

