Here's the Python function to achieve this:

```python
def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def contains_prime_factor(n):
    """Check if a number contains a prime number in its prime factorization."""
    if n <= 1:
        return False
    # Check for prime factors starting from 2
    for i in range(2, n + 1):
        if n % i == 0 and is_prime(i):
            return True
    return False

def max_value_with_conditions(d):
    """Compute the maximum value for each key in a dictionary based on conditions."""
    result = {}
    for key, value in d.items():
        if isinstance(value, int) and value % 3 == 0 and contains_prime_factor(value):
            result[key] = value
        else:
            result[key] = 0
    return result

# Example usage
d = {'a': 12, 'b': 20, 'c': 30}
print(max_value_with_conditions(d))
```

