import random

class InvalidInputError(Exception):
    pass

class Person:
    def __init__(self, name, age, gender, hobbies=None):
        self.set_name(name)
        self.set_age(age)
        self.set_gender(gender)
        self.hobbies = []
        if hobbies:
            for hobby in hobbies:
                self.add_hobby(hobby)

    def set_name(self, name):
        if not isinstance(name, str) or not (0 < len(name) <= 100):
            raise InvalidInputError("Name must be a non-empty string with a maximum length of 100 characters.")
        self.name = name

    def set_age(self, age):
        if not isinstance(age, int) or not (0 <= age <= 150):
            raise InvalidInputError("Age must be a positive integer between 0 and 150.")
        self.age = age

    def set_gender(self, gender):
        if gender not in ["male", "female"]:
            raise InvalidInputError("Gender must be either 'male' or 'female'.")
        self.gender = gender

    def add_hobby(self, hobby):
        if not isinstance(hobby, str) or not (0 < len(hobby) <= 100):
            raise InvalidInputError("Hobby must be a non-empty string with a maximum length of 100 characters.")
        if hobby not in self.hobbies:
            self.hobbies.append(hobby)

    def remove_hobby(self, hobby):
        if hobby in self.hobbies:
            self.hobbies.remove(hobby)

    def change_name(self, new_name):
        self.set_name(new_name)

    def change_age(self, new_age):
        self.set_age(new_age)

    def count_hobbies(self):
        return len(self.hobbies)

    def print_hobbies(self):
        if not self.hobbies:
            print("No hobbies to display.")
        else:
            for hobby in self.hobbies:
                print(hobby)

    def get_hobbies(self):
        return self.hobbies.copy()

    def has_hobby(self, hobby):
        return hobby in self.hobbies

    def get_random_hobby(self):
        if not self.hobbies:
            return None
        return random.choice(self.hobbies)

    def clear_hobbies(self):
        self.hobbies.clear()

# Example usage:
