    person.print_hobbies()
    print(f"Has hobby 'Swimming': {person.has_hobby('Swimming')}")
    print(f"Random hobby: {person.get_random_hobby()}")
    person.clear_hobbies()
    person.print_hobbies()
except InvalidInputError as e:
    print(e)
