```python
def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def product_of_primes_divisible_by_4(mylist):
    product = 1
    for number in mylist:
        if is_prime(number) and number % 4 == 0:
            product *= number
    return product

