```javascript
function isPrime(num) {
    if (num <= 1) return false;
    if (num <= 3) return true;

    if (num % 2 === 0 || num % 3 === 0) return false;

    for (let i = 5; i * i <= num; i += 6) {
        if (num % i === 0 || num % (i + 2) === 0) return false;
    }

    return true;
}

function checkNumber(input) {
    // Attempt to convert the input to a number
    let number = Number(input);

    // Check if the input is a valid number
    if (isNaN(number)) {
        console.log("Error: Input is not a valid number.");
        return;
    }

    // Check if the number is an integer
    if (!Number.isInteger(number)) {
        console.log("Error: Input is not an integer.");
        return;
    }

    // Check if the number is within the specified range
    if (number < 1 || number > 100) {
        console.log("Error: Number is out of the specified range (1-100).");
        return;
    }

    // Check if the number is prime
    if (isPrime(number)) {
        console.log(`The number ${number} is prime.`);
    } else {
        console.log(`The number ${number} is not prime.`);
    }
}

