```python
class GroceryInventory:
    def __init__(self):
        self.inventory = {}

    def add_item(self, name, quantity, price, nutritional_info):
        if len(name) > 50:
            raise ValueError("Name must be a string with a maximum length of 50 characters.")
        if not (1 <= quantity <= 1000):
            raise ValueError("Quantity must be an integer ranging from 1 to 1000.")
        if not (0.01 <= price <= 1000):
            raise ValueError("Price must be a float ranging from $0.01 to $1000.")
        if 'calories' not in nutritional_info or 'carbohydrates' not in nutritional_info:
            raise ValueError("Nutritional information must include calories and carbohydrates.")
        if not isinstance(nutritional_info['calories'], int):
            raise ValueError("Calories must be an integer.")
        if not isinstance(nutritional_info['carbohydrates'], float):
            raise ValueError("Carbohydrates must be a float.")

        self.inventory[name] = {
            'quantity': quantity,
            'price': price,
            'nutritional_info': nutritional_info
        }

    def remove_item(self, name):
        if name in self.inventory:
            del self.inventory[name]
        else:
            print(f"Item '{name}' not found in inventory.")

    def update_quantity(self, name, quantity):
        if name in self.inventory:
            if not (1 <= quantity <= 1000):
                raise ValueError("Quantity must be an integer ranging from 1 to 1000.")
            self.inventory[name]['quantity'] = quantity
        else:
            print(f"Item '{name}' not found in inventory.")

    def update_price(self, name, price):
        if name in self.inventory:
            if not (0.01 <= price <= 1000):
                raise ValueError("Price must be a float ranging from $0.01 to $1000.")
            self.inventory[name]['price'] = price
        else:
            print(f"Item '{name}' not found in inventory.")

    def get_nutritional_info(self, name):
        if name in self.inventory:
            return self.inventory[name]['nutritional_info']
        else:
            print(f"Item '{name}' not found in inventory.")
            return None

# Unit tests
def test_grocery_inventory():
    inventory = GroceryInventory()

    # Test adding items
    inventory.add_item("Apple", 100, 0.5, {'calories': 52, 'carbohydrates': 14.0})
    assert inventory.inventory["Apple"]['quantity'] == 100
    assert inventory.inventory["Apple"]['price'] == 0.5
    assert inventory.inventory["Apple"]['nutritional_info']['calories'] == 52

    # Test updating quantity
    inventory.update_quantity("Apple", 150)
    assert inventory.inventory["Apple"]['quantity'] == 150

    # Test updating price
    inventory.update_price("Apple", 0.6)
    assert inventory.inventory["Apple"]['price'] == 0.6

    # Test getting nutritional information
    nutritional_info = inventory.get_nutritional_info("Apple")
    assert nutritional_info['calories'] == 52
    assert nutritional_info['carbohydrates'] == 14.0

    # Test removing items
    inventory.remove_item("Apple")
    assert "Apple" not in inventory.inventory

    # Test removing non-existent item
    inventory.remove_item("Banana")  # Should handle gracefully

    print("All tests passed.")

# Run unit tests
test_grocery_inventory()
