import math

def is_prime(n, sieve=None):
    """Check if a number is prime using a sieve if available."""
    if n < 2:
        return False
    if sieve:
        return sieve[n]
    # Basic prime check for small numbers
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def sieve_of_eratosthenes(max_num):
    """Generate a sieve for prime numbers up to max_num."""
    sieve = [True] * (max_num + 1)
    sieve[0] = sieve[1] = False  # 0 and 1 are not prime numbers
    for start in range(2, int(math.sqrt(max_num)) + 1):
        if sieve[start]:
            for multiple in range(start*start, max_num + 1, start):
                sieve[multiple] = False
    return sieve

def sum_of_primes(numbers):
    """Return the sum of all prime numbers in the list."""
    if not isinstance(numbers, list) or not all(isinstance(x, int) for x in numbers):
        raise ValueError("Input must be a list of integers.")

    if not numbers:
        return 0

    max_num = max(numbers)
    sieve = sieve_of_eratosthenes(max_num) if max_num > 1 else None

    prime_sum = sum(x for x in numbers if is_prime(x, sieve))
    return prime_sum

# Unit tests
import unittest

class TestSumOfPrimes(unittest.TestCase):
    def test_empty_list(self):
        self.assertEqual(sum_of_primes([]), 0)

    def test_no_primes(self):
        self.assertEqual(sum_of_primes([0, 1, -1, -10]), 0)

    def test_small_primes(self):
        self.assertEqual(sum_of_primes([2, 3, 4, 5, 6]), 10)

    def test_large_primes(self):
        self.assertEqual(sum_of_primes([101, 103, 107]), 311)

    def test_mixed_numbers(self):
        self.assertEqual(sum_of_primes([10, 11, 12, 13, 14, 15]), 24)

    def test_invalid_input(self):
        with self.assertRaises(ValueError):
            sum_of_primes("not a list")

    def test_large_numbers(self):
        self.assertEqual(sum_of_primes([999983, 1000000]), 999983)

if __name__ == "__main__":
    unittest.main()
```

