To solve this problem using bitwise operators without loops or recursion, we can use the binary GCD algorithm, which is efficient and well-suited for this task. The algorithm relies on the properties of even and odd numbers and uses bitwise operations to find the greatest common divisor (GCD). Here's a Python implementation of the solution, along with unit tests:

```python
def hcf_bitwise(a, b):
    # Validate input types
    if not isinstance(a, int) or not isinstance(b, int):
        raise ValueError("Both inputs must be integers.")

    # Handle edge cases
    if a == 0:
        return abs(b)
    if b == 0:
        return abs(a)

    # Make both numbers positive
    a, b = abs(a), abs(b)

    # Helper function to find the greatest power of 2 that divides both a and b
    def gcd_bitwise(x, y):
        if x == y:
            return x
        if x == 0:
            return y
        if y == 0:
            return x

        # x and y are both even
        if (x & 1) == 0 and (y & 1) == 0:
            return gcd_bitwise(x >> 1, y >> 1) << 1

        # x is even, y is odd
        if (x & 1) == 0:
            return gcd_bitwise(x >> 1, y)

        # x is odd, y is even
        if (y & 1) == 0:
            return gcd_bitwise(x, y >> 1)

        # Both x and y are odd, x > y
        if x > y:
            return gcd_bitwise((x - y) >> 1, y)

        # Both x and y are odd, x <= y
        return gcd_bitwise((y - x) >> 1, x)

    return gcd_bitwise(a, b)

# Unit tests
import unittest

class TestHCFBitwise(unittest.TestCase):
    def test_positive_numbers(self):
        self.assertEqual(hcf_bitwise(48, 18), 6)
        self.assertEqual(hcf_bitwise(101, 103), 1)
        self.assertEqual(hcf_bitwise(56, 98), 14)

    def test_negative_numbers(self):
        self.assertEqual(hcf_bitwise(-48, 18), 6)
        self.assertEqual(hcf_bitwise(48, -18), 6)
        self.assertEqual(hcf_bitwise(-48, -18), 6)

    def test_zero_cases(self):
        self.assertEqual(hcf_bitwise(0, 18), 18)
        self.assertEqual(hcf_bitwise(48, 0), 48)
        self.assertEqual(hcf_bitwise(0, 0), 0)

    def test_large_numbers(self):
        self.assertEqual(hcf_bitwise(1234567890, 987654321), 9)
        self.assertEqual(hcf_bitwise(2**20, 2**15), 2**15)

    def test_invalid_input(self):
        with self.assertRaises(ValueError):
            hcf_bitwise(48, "18")
        with self.assertRaises(ValueError):
            hcf_bitwise("48", 18)
        with self.assertRaises(ValueError):
            hcf_bitwise(48.0, 18)

if __name__ == "__main__":
    unittest.main()
```

