class Rectangle:
    def __init__(self, length, width):
        self.length = length
        self.width = width

    def calculate_area(self):
        return self.length * self.width

    def calculate_perimeter(self):
        return 2 * (self.length + self.width)

    def is_square(self):
        return self.length == self.width


def create_rectangle(length, width, perimeter):
    if (length + width) * 2 != perimeter:
        raise ValueError("Invalid perimeter value")
    return Rectangle(length, width)


def print_rectangle_info(rectangle):
    print("Rectangle Info:")
    print("Length:", rectangle.length)
    print("Width:", rectangle.width)
    print("Area:", rectangle.calculate_area())
    print("Perimeter:", rectangle.calculate_perimeter())
    print("Is Square:", rectangle.is_square())


try:
