```python
import re
from datetime import datetime

class Person:
    MAX_HOBBIES = 10
    MAX_ADDRESSES = 5

    def __init__(self, name, age, hobbies, addresses):
        self.name = self.validate_name(name)
        self.age = self.validate_age(age)
        self.hobbies = self.validate_hobbies(hobbies)
        self.addresses = self.validate_addresses(addresses)
        self.address_id_counter = len(addresses)

    def validate_name(self, name):
        if not name or not re.match("^[A-Za-z ]+$", name):
            raise ValueError("Name must contain only letters and spaces.")
        return name.title()

    def validate_age(self, age):
        if not isinstance(age, int) or age <= 0:
            raise ValueError("Age must be a positive integer.")
        return age

    def validate_hobbies(self, hobbies):
        if len(hobbies) > self.MAX_HOBBIES:
            raise ValueError(f"Cannot have more than {self.MAX_HOBBIES} hobbies.")
        for hobby in hobbies:
            if not hobby or not re.match("^[A-Za-z ]+$", hobby):
                raise ValueError("Hobbies must contain only letters and spaces.")
        return hobbies

    def validate_addresses(self, addresses):
        if len(addresses) > self.MAX_ADDRESSES:
            raise ValueError(f"Cannot have more than {self.MAX_ADDRESSES} addresses.")
        validated_addresses = {}
        for address_id, address in addresses.items():
            validated_addresses[address_id] = self.validate_address(address)
        return validated_addresses

    def validate_address(self, address):
        street, house_number, city, state, zip_code = address
        if not street or not re.match("^[A-Za-z ]{1,50}$", street):
            raise ValueError("Street name must contain only letters and spaces, max 50 characters.")
        if not house_number or not re.match("^[A-Za-z0-9 ]{1,50}$", house_number):
            raise ValueError("House number must contain only letters, numbers, and spaces, max 50 characters.")
        if not city or not re.match("^[A-Za-z ]{1,50}$", city):
            raise ValueError("City must contain only letters and spaces, max 50 characters.")
        if not state or not re.match("^[A-Za-z ]{1,50}$", state):
            raise ValueError("State must contain only letters and spaces, max 50 characters.")
        if not re.match("^\d{5}$", zip_code):
            raise ValueError("Zip code must be a 5-digit number.")
        return (street.title(), house_number, city.title(), state.title(), zip_code)

    def add_hobby(self, hobby):
        if len(self.hobbies) >= self.MAX_HOBBIES:
            raise ValueError(f"Cannot have more than {self.MAX_HOBBIES} hobbies.")
        if not hobby or not re.match("^[A-Za-z ]+$", hobby):
            raise ValueError("Hobby must contain only letters and spaces.")
        self.hobbies.append(hobby)

    def remove_hobby(self, hobby):
        if hobby in self.hobbies:
            self.hobbies.remove(hobby)

    def calculate_age_in_months(self):
        return self.age * 12

    def calculate_birth_year(self):
        current_year = datetime.now().year
        birth_year = current_year - self.age
        if not (1000 <= birth_year <= 9999):
            raise ValueError("Calculated birth year is not a valid 4-digit number.")
        return birth_year

    def full_address(self, address_id):
        if address_id not in self.addresses:
            raise ValueError("Address ID not found.")
        address = self.addresses[address_id]
        full_address = f"{address[0]}, {address[1]}, {address[2]}, {address[3]}, {address[4]}"
        if len(full_address) > 250:
            raise ValueError("Full address exceeds maximum length of 250 characters.")
        return full_address

    def display_person_data(self):
        print(f"Name: {self.name}")
        print(f"Age: {self.age} years ({self.calculate_age_in_months()} months)")
        print(f"Birth Year: {self.calculate_birth_year()}")
        print("Hobbies:", ", ".join(self.hobbies))
        print("Addresses:")
        for address_id, address in self.addresses.items():
            print(f"  {address_id}: {self.full_address(address_id)}")

    def add_address(self, street, house_number, city, state, zip_code):
        if len(self.addresses) >= self.MAX_ADDRESSES:
            raise ValueError(f"Cannot have more than {self.MAX_ADDRESSES} addresses.")
        self.address_id_counter += 1
        self.addresses[self.address_id_counter] = self.validate_address((street, house_number, city, state, zip_code))

    def remove_address(self, address_id):
        if address_id in self.addresses:
            del self.addresses[address_id]

    def search_hobby(self, hobby):
        hobby = hobby.lower()
        return any(hobby in h.lower() for h in self.hobbies)

# Example usage
try:
    person = Person(
        name="John Doe",
        age=30,
        hobbies=["Reading", "Swimming"],
        addresses={
            1: ("Main Street", "123", "Springfield", "Illinois", "62704")
        }
    )
    person.display_person_data()
    person.add_hobby("Cycling")
    person.add_address("Elm Street", "456", "Springfield", "Illinois", "62705")
    print("Hobby 'Cycling' exists:", person.search_hobby("Cycling"))
    person.display_person_data()
except ValueError as e:
    print("Error:", e)
