```python
import math
import unittest

def replace_special_values(data):
    if isinstance(data, list):
        return [replace_special_values(item) for item in data]
    elif isinstance(data, dict):
        return {key: replace_special_values(value) for key, value in data.items()}
    elif isinstance(data, (int, float)):
        if isinstance(data, float) and math.isnan(data):
            return 0
        elif data < 0:
            return 0
        elif data > 0 and data % 2 == 0:
            return 1
        else:
            return data
    elif data in (None, ''):
        return 0
    else:
        return data

# Unit tests
class TestReplaceSpecialValues(unittest.TestCase):
    def test_basic_list(self):
        self.assertEqual(replace_special_values([5, -2, 3, None, '', 8]), [1, 0, 3, 0, 0, 1])

    def test_basic_dict(self):
        self.assertEqual(replace_special_values({'a': 1, 'b': '', 'c': None, 'd': [1, '', None]}),
                         {'a': 1, 'b': 0, 'c': 0, 'd': [1, 0, 0]})

    def test_nested_structures(self):
        self.assertEqual(replace_special_values([1, [2, '', [None]], {'a': '', 'b': [3, None, '']}]),
                         [1, [1, 0, [0]], {'a': 0, 'b': [3, 0, 0]}])

    def test_mixed_data_types(self):
        self.assertEqual(replace_special_values([1, 'string', -5, 4.0, float('nan')]),
                         [1, 'string', 0, 1, 0])

    def test_deeply_nested(self):
        self.assertEqual(replace_special_values({'a': {'b': {'c': [2, -3, '', None]}}}),
                         {'a': {'b': {'c': [1, 0, 0, 0]}}})

    def test_no_special_values(self):
        self.assertEqual(replace_special_values([1, 3, 5]), [1, 3, 5])

    def test_all_special_values(self):
        self.assertEqual(replace_special_values(['', None, -1, 2, float('nan')]), [0, 0, 0, 1, 0])

if __name__ == '__main__':
    unittest.main()
```

