Here's the implementation:

```python
def count_occurrences(data, item):
    if not isinstance(data, (list, dict)):
        raise TypeError("Input data must be a list or dictionary.")

    def recursive_count(data, item, depth=0):
        count = 0
        if isinstance(data, list):
            for element in data:
                if element == item:
                    count += 1
                elif isinstance(element, (list, dict)) and depth == 0:
                    count += recursive_count(element, item, depth + 1)
        elif isinstance(data, dict):
            for key, value in data.items():
                if key == item or value == item:
                    count += 1
                elif isinstance(value, (list, dict)) and depth == 0:
                    count += recursive_count(value, item, depth + 1)
        return count

    return recursive_count(data, item)

# Unit tests
def run_tests():
    test_cases = [
        # Test case 1: Simple list
        ([1, 2, 3, 2, 4], 2, 2),
        # Test case 2: Nested list
        ([1, 2, [2, 3], 4], 2, 2),
        # Test case 3: Nested dictionary
        ({"a": 2, "b": {"c": 2}}, 2, 2),
        # Test case 4: Mixed nested structures
        ([1, 2, 3, [2, 4, {"a": [2, 3]}, [3, 4]], {"a": 2, "b": [1, {"c": 2}]}, [5, 6]], 2, 3),
        # Test case 5: Empty list
        ([], 2, 0),
        # Test case 6: Deeply nested structures
        ([1, [2, [3, [4, [5, 2]]]]], 2, 1),
        # Test case 7: Invalid input type
        ("string", 2, TypeError),
    ]

    for i, (data, item, expected) in enumerate(test_cases):
        try:
            result = count_occurrences(data, item)
            assert result == expected, f"Test case {i+1} failed: expected {expected}, got {result}"
        except TypeError as e:
            assert expected == TypeError, f"Test case {i+1} failed: expected TypeError, got {e}"

    print("All test cases passed!")

# Instructions to run the tests
if __name__ == "__main__":
    run_tests()
```

