Certainly! Below is the Python code that defines a function to remove all occurrences of a given substring from a string while maintaining the original order of characters. It also includes unit tests to cover various scenarios:

```python
def remove_substring(original_string, substring):
    if not original_string or not substring:
        return original_string

    words = original_string.split()
    result = [word for word in words if word != substring]
    return ' '.join(result)

# Unit tests
import unittest

class TestRemoveSubstring(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(remove_substring("", "o"), "")

    def test_empty_substring(self):
        self.assertEqual(remove_substring("The quick brown fox", ""), "The quick brown fox")

    def test_no_occurrences(self):
        self.assertEqual(remove_substring("The quick brown fox", "cat"), "The quick brown fox")

    def test_single_occurrence(self):
        self.assertEqual(remove_substring("The quick brown fox", "fox"), "The quick brown")

    def test_multiple_occurrences(self):
        self.assertEqual(remove_substring("o o o o", "o"), "")

    def test_case_sensitive(self):
        self.assertEqual(remove_substring("The quick brown fox jumped over the lazy dog", "o"), "The quick brown fox jumped over the lazy dog")

    def test_substring_at_start(self):
        self.assertEqual(remove_substring("fox The quick brown fox", "fox"), "The quick brown")

    def test_substring_at_end(self):
        self.assertEqual(remove_substring("The quick brown fox fox", "fox"), "The quick brown")

    def test_substring_in_middle(self):
        self.assertEqual(remove_substring("The quick fox brown fox", "fox"), "The quick brown")

if __name__ == "__main__":
    unittest.main()
```

