from datetime import datetime, timedelta

class LivingBeing:
    def __init__(self, name):
        self.name = name

class Animal(LivingBeing):
    species_lifespans = {
        'dog': 13,
        'cat': 15,
        'parrot': 50,
        'goldfish': 10
    }

    species_foods = {
        'dog': ['meat', 'bones'],
        'cat': ['fish', 'meat'],
        'parrot': ['seeds', 'fruits'],
        'goldfish': ['flakes', 'worms']
    }

    species_sounds = {
        'dog': 'Bark',
        'cat': 'Meow',
        'parrot': 'Squawk',
        'goldfish': 'Blub'
    }

    def __init__(self, name, species):
        super().__init__(name)
        self.species = species
        self.creation_date = datetime.now()
        self.age = 0  # Age in years

    @property
    def calculated_age(self):
        lifespan = self.get_average_lifespan(self.species)
        time_alive = datetime.now() - self.creation_date
        return min(time_alive.days / 365, lifespan)

    def eat(self, food):
        if food not in self.species_foods[self.species]:
            raise ValueError(f"{food} is not a valid food for a {self.species}.")

        # Simulate nutritional value and metabolic rate impact
        nutritional_value = 0.1  # Arbitrary value
        metabolic_rate = 0.05  # Arbitrary value
        self.age += nutritional_value - metabolic_rate

    @staticmethod
    def compare_age(animal1, animal2):
        return animal1.calculated_age > animal2.calculated_age

    @staticmethod
    def get_average_lifespan(species):
        return Animal.species_lifespans.get(species, 0)

    def reproduce(self):
        return Animal(self.name + " Jr.", self.species)

    def speak(self):
        print(self.species_sounds.get(self.species, "Sound"))

    def move(self):
        print(f"The {self.species} moves.")

class Mammal(Animal):
    def __init__(self, name, species, fur_color):
        super().__init__(name, species)
        self.fur_color = fur_color

    def milk(self):
        print(f"The {self.species} is producing milk.")

    def move(self):
        print(f"The {self.species} walks or runs.")

class Bird(Animal):
    def __init__(self, name, species, wing_span):
        super().__init__(name, species)
        self.wing_span = wing_span

    def fly(self):
        print(f"The {self.species} is flying.")

    def move(self):
        print(f"The {self.species} flies.")

class Fish(Animal):
    def __init__(self, name, species, water_type):
        super().__init__(name, species)
        self.water_type = water_type

    def swim(self):
        print(f"The {self.species} is swimming.")

    def move(self):
        print(f"The {self.species} swims.")

# Example usage:
dog = Mammal("Buddy", "dog", "brown")
cat = Mammal("Whiskers", "cat", "black")
parrot = Bird("Polly", "parrot", 0.5)
goldfish = Fish("Goldie", "goldfish", "freshwater")

dog.eat("meat")
cat.eat("fish")
parrot.eat("seeds")
goldfish.eat("flakes")

print(Animal.compare_age(dog, cat))
