        return any(isinstance(element, complex) for row in matrix for element in row)

    # Check if matrices contain elements of different data types
    def has_mixed_data_types(matrix):
        first_type = type(matrix[0][0])
        return any(type(element) != first_type for row in matrix for element in row)

    # Validate matrix_a
    if not is_valid_matrix(matrix_a):
        raise ValueError("Matrix A is not a valid matrix. All rows must have the same number of columns.")

    # Validate matrix_b
    if not is_valid_matrix(matrix_b):
        raise ValueError("Matrix B is not a valid matrix. All rows must have the same number of columns.")

    # Check for complex numbers
    if contains_complex(matrix_a) or contains_complex(matrix_b):
        raise ValueError("Matrix multiplication with complex numbers is not supported.")

    # Check for mixed data types
    if has_mixed_data_types(matrix_a) or has_mixed_data_types(matrix_b):
        raise ValueError("Matrices contain elements of different data types.")

    # Check for dimension compatibility
    if matrix_a and matrix_b and len(matrix_a[0]) != len(matrix_b):
        raise ValueError("Incompatible dimensions: The number of columns in Matrix A must be equal to the number of rows in Matrix B.")

    # If either matrix is empty, return an empty matrix
    if not matrix_a or not matrix_b:
        return []

    # Perform matrix multiplication
    num_rows_a = len(matrix_a)
    num_cols_a = len(matrix_a[0])
    num_cols_b = len(matrix_b[0])

    result = [[0] * num_cols_b for _ in range(num_rows_a)]

    for i in range(num_rows_a):
        for j in range(num_cols_b):
            for k in range(num_cols_a):
                result[i][j] += matrix_a[i][k] * matrix_b[k][j]

    return result

# Example usage:
