matrix_b = [[7, 8], [9, 10], [11, 12]]

try:
    result = multiply_matrices(matrix_a, matrix_b)
    print("Resulting Matrix:")
    for row in result:
        print(row)
except ValueError as e:
    print("Error:", e)
