import subprocess
import psutil
import time

def task_func(process_name: str) -> str:
    # Check if the process is running
    for proc in psutil.process_iter(['name']):
        try:
            if proc.info['name'] == process_name:
                # Process found, terminate it
                proc.terminate()
                try:
                    proc.wait(timeout=5)  # Wait for the process to terminate
                except psutil.TimeoutExpired:
                    proc.kill()  # Force kill if it didn't terminate in time
                except Exception as e:
                    return f"Error terminating process {process_name}: {e}"

                # Restart the process
                try:
                    subprocess.Popen(process_name)
                    return f"Process found. Restarting {process_name}."
                except Exception as e:
                    return f"Error starting process {process_name}: {e}"

    # Process not found, start it
    try:
        subprocess.Popen(process_name)
        return f"Process not found. Starting {process_name}."
    except Exception as e:
        return f"Error starting process {process_name}: {e}"
```

This function uses the `psutil` library to iterate over all running processes and checks if any of them match the given `process_name`. If a matching process is found, it attempts to terminate it gracefully and waits for it to fully terminate before restarting it using `subprocess.Popen`. If no matching process is found, it starts the process directly. The function handles exceptions that may occur during process termination and starting, and returns a message indicating the action taken.

