```python
import json
import os
import re

def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"
):
    # Check if the file exists
    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    # Open and read the JSON file
    try:
        with open(file_path, 'r') as file:
            try:
                data = json.load(file)
            except json.JSONDecodeError:
                raise ValueError("Invalid JSON format")
    except Exception as e:
        raise ValueError(f"Error reading file: {e}")

    # Validate required fields
    for field in INPUT_JSON["required"]:
        if field not in data:
            raise ValueError(f"Missing required attribute: {field}")

    # Validate types
    for field, field_type in INPUT_JSON["properties"].items():
        if not isinstance(data.get(field), field_type["type"]):
            raise ValueError(f"Incorrect type for attribute '{field}'. Expected {field_type['type']}.")

    # Validate email format
    email = data.get("email")
    if not re.match(EMAIL_REGEX, email):
        raise ValueError("Invalid email format")

    # Sanitize attribute input
    if not isinstance(attribute, str) or attribute not in INPUT_JSON["properties"]:
        raise ValueError("Invalid attribute requested")

    # Return the specified attribute value
    return data.get(attribute)

# Example usage:
