import re
import requests

def task_func(input):
    # Sanitize the input to prevent injection attacks
    sanitized_input = re.sub(r'[^\w:/?&.=]', '', input)

    # Extract the API endpoint using regex
    endpoint_match = re.search(r'https?://[^\s]+', sanitized_input)
    if not endpoint_match:
        return {"error": "No valid API endpoint found"}

    endpoint = endpoint_match.group(0)

    try:
        # Send a GET request to the endpoint
        response = requests.get(endpoint)

        # Check if the response status code is 200
        if response.status_code == 200:
            try:
                # Attempt to parse the response data as JSON
                response_data = response.json()
            except ValueError:
                # If the response is not JSON, return the raw text
                response_data = {"data": response.text}
        else:
            response_data = {"error": f"Request failed with status code {response.status_code}"}

    except requests.RequestException as e:
        response_data = {"error": str(e)}

    return response_data
```

This function sanitizes the input to prevent injection attacks, extracts the API endpoint using regex, sends a GET request to the endpoint, checks the response status code, and processes the response data accordingly. If the response is not in JSON format, it returns the raw text within a dictionary.

