To create a simple mathematical expression parser and evaluator with the specified features, we can implement a class `Runtime` that handles variable assignments, function definitions, and arithmetic operations. We'll use Python's built-in `math` module for trigonometric functions and define a simple grammar for parsing expressions. Here's a basic implementation:

```python
import math
import re

class Runtime:
    def __init__(self):
        self.variables = {}
        self.functions = {}

    def evaluate(self, expression):
        try:
            return self._eval(expression)
        except Exception as e:
            return f"Error: {str(e)}"

    def _eval(self, expression):
        expression = expression.strip()
        if '=' in expression:
            var, expr = map(str.strip, expression.split('=', 1))
            value = self._eval(expr)
            self.variables[var] = value
            return value
        elif ':' in expression:
            func_def, expr = map(str.strip, expression.split(':', 1))
            func_name, params = self._parse_function_definition(func_def)
            self.functions[func_name] = (params, expr)
            return f"Function {func_name} defined"
        else:
            return self._eval_expr(expression)

    def _parse_function_definition(self, func_def):
        match = re.match(r'(\w+)\(([\w,]*)\)', func_def)
        if not match:
            raise ValueError("Invalid function definition")
        func_name = match.group(1)
        params = [p.strip() for p in match.group(2).split(',') if p.strip()]
        return func_name, params

    def _eval_expr(self, expr):
        expr = expr.replace(' ', '')
        return self._eval_term(expr)

    def _eval_term(self, expr):
        if '(' in expr:
            return self._eval_parentheses(expr)
        for op in ('+', '-'):
            left, op, right = self._split_expr(expr, op)
            if op:
                return self._apply_op(op, self._eval_term(left), self._eval_term(right))
        return self._eval_factor(expr)

    def _eval_factor(self, expr):
        for op in ('*', '/'):
            left, op, right = self._split_expr(expr, op)
            if op:
                return self._apply_op(op, self._eval_factor(left), self._eval_factor(right))
        return self._eval_atom(expr)

    def _eval_atom(self, expr):
        if expr.isdigit() or (expr.startswith('-') and expr[1:].isdigit()):
            return float(expr)
        if expr in self.variables:
            return self.variables[expr]
        if '(' in expr:
            return self._eval_function_call(expr)
        raise ValueError(f"Undefined variable or function: {expr}")

    def _eval_parentheses(self, expr):
        if expr.startswith('(') and expr.endswith(')'):
            return self._eval_expr(expr[1:-1])
        raise ValueError("Mismatched parentheses")

    def _eval_function_call(self, expr):
        match = re.match(r'(\w+)\((.*)\)', expr)
        if not match:
            raise ValueError("Invalid function call")
        func_name = match.group(1)
        args = self._parse_arguments(match.group(2))
        if func_name in self.functions:
            params, body = self.functions[func_name]
            if len(args) != len(params):
                raise ValueError("Argument count mismatch")
            local_scope = {param: self._eval(arg) for param, arg in zip(params, args)}
            return self._eval_with_scope(body, local_scope)
        elif func_name in dir(math):
            func = getattr(math, func_name)
            return func(*map(self._eval, args))
        else:
            raise ValueError(f"Undefined function: {func_name}")

    def _parse_arguments(self, args_str):
        return [arg.strip() for arg in args_str.split(',') if arg.strip()]

    def _eval_with_scope(self, expr, local_scope):
        original_scope = self.variables.copy()
        self.variables.update(local_scope)
        try:
            return self._eval_expr(expr)
        finally:
            self.variables = original_scope

    def _split_expr(self, expr, operator):
        depth = 0
        for i, char in enumerate(expr):
            if char == '(':
                depth += 1
            elif char == ')':
                depth -= 1
            elif char == operator and depth == 0:
                return expr[:i], operator, expr[i+1:]
        return expr, None, None

    def _apply_op(self, op, left, right):
        if op == '+':
            return left + right
        elif op == '-':
            return left - right
        elif op == '*':
            return left * right
        elif op == '/':
            if right == 0:
                raise ValueError("Division by zero")
            return left / right
        else:
            raise ValueError(f"Unknown operator: {op}")

    def shell(self):
        print("Welcome to the interactive shell. Type 'exit()' to quit.")
        while True:
            try:
                command = input(">>> ").strip()
                if command == "exit()":
                    break
                elif command == "vars":
                    print(self.variables)
                elif command == "funcs":
                    print(self.functions)
                else:
                    result = self.evaluate(command)
                    print(result)
            except Exception as e:
                print(f"Error: {str(e)}")

# Example usage
runtime = Runtime()
runtime.shell()
```

