```python
from flask import Flask, request, jsonify

app = Flask(__name__)

def validate_input(data):
    """Validate that the input data contains two integers."""
    try:
        n1 = int(data.get('N1'))
        n2 = int(data.get('N2'))
        return n1, n2, None
    except (ValueError, TypeError):
        return None, None, "Invalid input: N1 and N2 must be integers."

@app.route('/add', methods=['POST'])
def add():
    n1, n2, error = validate_input(request.json)
    if error:
        return jsonify({'error': error}), 400
    result = n1 + n2
    return jsonify({'result': result})

@app.route('/sub', methods=['POST'])
def sub():
    n1, n2, error = validate_input(request.json)
    if error:
        return jsonify({'error': error}), 400
    result = n1 - n2
    return jsonify({'result': result})

@app.route('/mul', methods=['POST'])
def mul():
    n1, n2, error = validate_input(request.json)
    if error:
        return jsonify({'error': error}), 400
    result = n1 * n2
    return jsonify({'result': result})

@app.route('/div', methods=['POST'])
def div():
    n1, n2, error = validate_input(request.json)
    if error:
        return jsonify({'error': error}), 400
    if n2 == 0:
        return jsonify({'error': 'Division by zero is not allowed.'}), 400
    result = n1 / n2
    return jsonify({'result': result})

@app.route('/bitand', methods=['POST'])
def bitand():
    n1, n2, error = validate_input(request.json)
    if error:
        return jsonify({'error': error}), 400
    result = n1 & n2
    return jsonify({'result': result})

if __name__ == '__main__':
    app.run(debug=True)
