# result_processor.py

class ResultProcessor:
    def run(self, result, per_page=None):
        if 'page' not in result.get('metadata', {}):
            raise ValueError("The 'metadata' dictionary must contain a 'page' key.")

        data = result.get('data', [])
        page = result['metadata']['page']

        if not data:
            return {'data': [], 'metadata': {'page': page, 'perPage': 0}}

        if per_page is None:
            per_page = len(data)

        start_index = (page - 1) * per_page
        end_index = start_index + per_page

        paginated_data = data[start_index:end_index]

        return {'data': paginated_data, 'metadata': {'page': page, 'perPage': len(paginated_data)}}

# test_result_processor.py

