    (pytest.lazy_fixture('sample_result'), 5, {'data': [1, 2, 3, 4, 5], 'metadata': {'page': 1, 'perPage': 5}}),
    (pytest.lazy_fixture('empty_result'), None, {'data': [], 'metadata': {'page': 1, 'perPage': 0}}),
])
