To implement the `InventoryManager` class with the specified functionalities, we need to define custom exceptions for handling specific error cases, such as when an item already exists, when an item does not exist, when a business logic condition is violated, and when a user does not have access. Here's how you can design the class:

```python
class UniqueConstraintFailedException(Exception):
    """Exception raised when trying to add an item that already exists."""
    pass

class DoesNotExistException(Exception):
    """Exception raised when trying to access or modify an item that does not exist."""
    pass

class BusinessLogicException(Exception):
    """Exception raised when a business logic condition is violated."""
    pass

class NoAccessException(Exception):
    """Exception raised when a user does not have access to modify the inventory."""
    pass

class InventoryManager:
    def __init__(self):
        self.inventory = {}
        self.required_role = 'admin'

    def check_access(self, user_role):
        if user_role != self.required_role:
            raise NoAccessException("User does not have access to modify the inventory.")

    def add_item(self, item_id, quantity, user_role):
        self.check_access(user_role)
        if quantity < 0:
            raise BusinessLogicException("Quantity must be a non-negative integer.")
        if item_id in self.inventory:
            raise UniqueConstraintFailedException(f"Item with ID {item_id} already exists.")
        self.inventory[item_id] = quantity

    def remove_item(self, item_id, user_role):
        self.check_access(user_role)
        if item_id not in self.inventory:
            raise DoesNotExistException(f"Item with ID {item_id} does not exist.")
        del self.inventory[item_id]

    def update_quantity(self, item_id, quantity, user_role):
        self.check_access(user_role)
        if item_id not in self.inventory:
            raise DoesNotExistException(f"Item with ID {item_id} does not exist.")
        if quantity < 0:
            raise BusinessLogicException("Quantity cannot be less than 0.")
        self.inventory[item_id] = quantity

    def get_item_quantity(self, item_id):
        if item_id not in self.inventory:
            raise DoesNotExistException(f"Item with ID {item_id} does not exist.")
        return self.inventory[item_id]

    def get_total_items(self):
        return len(self.inventory)

# Example usage:
# inventory_manager = InventoryManager()
# inventory_manager.add_item('item1', 10, 'admin')
# print(inventory_manager.get_item_quantity('item1'))
# inventory_manager.update_quantity('item1', 5, 'admin')
# print(inventory_manager.get_total_items())
```

### Key Points:
- **Custom Exceptions**: Four custom exceptions are defined to handle specific error cases.
- **Access Control**: The `check_access` method ensures that only users with the 'admin' role can modify the inventory.
- **Inventory Management**: Methods for adding, removing, and updating items include checks for item existence and quantity constraints.
- **Data Encapsulation**: The inventory is stored in a dictionary, with item IDs as keys and quantities as values, encapsulated within the class.

