```python
from typing import List, Dict, Any

class QueueDelta:
    def __init__(self):
        pass

    def calculate(self, old_queues: List[Dict[str, Any]], new_queues: List[Dict[str, Any]]) -> Dict[str, List[Dict[str, Any]]]:
        if not isinstance(old_queues, list) or not isinstance(new_queues, list):
            raise ValueError("Both old_queues and new_queues should be lists.")

        old_queues_dict = {queue['name']: queue for queue in old_queues}
        new_queues_dict = {queue['name']: queue for queue in new_queues}

        added = []
        removed = []
        penalty_updated = []

        # Detect added queues
        for queue_name, new_queue in new_queues_dict.items():
            if queue_name not in old_queues_dict:
                added.append(new_queue)
            else:
                # Check for penalty updates
                old_queue = old_queues_dict[queue_name]
                if old_queue['penalty'] != new_queue['penalty']:
                    penalty_updated.append(new_queue)

        # Detect removed queues
        for queue_name, old_queue in old_queues_dict.items():
            if queue_name not in new_queues_dict:
                removed.append(old_queue)

        return {
            'added': added,
            'removed': removed,
            'penalty_updated': penalty_updated
        }


class OnAgentUpdatedManager:
    def __init__(self, add_to_queue_action, remove_from_queue_action, update_penalty_action):
        self.add_to_queue_action = add_to_queue_action
        self.remove_from_queue_action = remove_from_queue_action
        self.update_penalty_action = update_penalty_action

    def on_agent_updated(self, agent: Dict[str, Any]):
        if not isinstance(agent, dict) or 'old_queues' not in agent or 'new_queues' not in agent:
            raise ValueError("Agent object must be a dictionary containing 'old_queues' and 'new_queues'.")

        old_queues = agent['old_queues']
        new_queues = agent['new_queues']

        queue_delta = QueueDelta()
        changes = queue_delta.calculate(old_queues, new_queues)

        for queue in changes['added']:
            self.add_to_queue_action(agent, queue)

        for queue in changes['removed']:
            self.remove_from_queue_action(agent, queue)

        for queue in changes['penalty_updated']:
            self.update_penalty_action(agent, queue)


# Mock action handlers for demonstration purposes
def add_to_queue_action(agent, queue):
    print(f"Adding agent {agent['id']} to queue {queue['name']} with penalty {queue['penalty']}.")

def remove_from_queue_action(agent, queue):
    print(f"Removing agent {agent['id']} from queue {queue['name']}.")

def update_penalty_action(agent, queue):
    print(f"Updating penalty for agent {agent['id']} in queue {queue['name']} to {queue['penalty']}.")


# Example usage
if __name__ == "__main__":
    agent = {
        'id': 1,
        'old_queues': [
            {'name': 'sales', 'penalty': 1},
            {'name': 'support', 'penalty': 2}
        ],
        'new_queues': [
            {'name': 'sales', 'penalty': 1},
            {'name': 'support', 'penalty': 3},
            {'name': 'billing', 'penalty': 1}
        ]
    }

    manager = OnAgentUpdatedManager(add_to_queue_action, remove_from_queue_action, update_penalty_action)
    manager.on_agent_updated(agent)
```

### Explanation:

1. **QueueDelta Class**: This class has a `calculate` method that compares two lists of queue objects (`old_queues` and `new_queues`). It identifies queues that have been added, removed, or had their penalty updated. The method returns a dictionary with three lists: `added`, `removed`, and `penalty_updated`.

2. **OnAgentUpdatedManager Class**: This class manages the updates for an agent. It validates the agent object and uses the `QueueDelta` class to determine changes. It then calls the appropriate action handlers (`add_to_queue_action`, `remove_from_queue_action`, `update_penalty_action`) based on the detected changes.

3. **Mock Action Handlers**: These are simple print functions that simulate the actions of adding, removing, or updating an agent in a queue.

4. **Example Usage**: Demonstrates how to use the `OnAgentUpdatedManager` with a sample agent object.

