```python
def string_operations(s, operations):
    def slice_operation(s, start, end):
        try:
            return s[start:end]
        except IndexError:
            return ""

    def check_operation(s, sub):
        return sub in s

    def concat_operation(s, str_to_add):
        return s + str_to_add

    def format_operation(s, values):
        try:
            return s.format(*values)
        except (IndexError, KeyError):
            raise ValueError("The number of placeholders does not match the number of values provided.")

    results = []
    for operation in operations:
        if not operation or not isinstance(operation, tuple) or len(operation) < 2:
            raise ValueError("Each operation must be a tuple with at least an operation name and parameters.")

        op_name = operation[0]
        params = operation[1:]

        if op_name == "slice":
            if len(params) != 2 or not all(isinstance(i, int) for i in params):
                raise ValueError("Slice operation requires two integer parameters: start and end.")
            results.append(slice_operation(s, *params))
        elif op_name == "check":
            if len(params) != 1 or not isinstance(params[0], str):
                raise ValueError("Check operation requires one string parameter: sub.")
            results.append(check_operation(s, *params))
        elif op_name == "concat":
            if len(params) != 1 or not isinstance(params[0], str):
                raise ValueError("Concat operation requires one string parameter: str_to_add.")
            results.append(concat_operation(s, *params))
        elif op_name == "format":
            if len(params) != 1 or not isinstance(params[0], list):
                raise ValueError("Format operation requires one list parameter: values.")
            results.append(format_operation(s, *params))
        else:
            raise ValueError(f"Unsupported operation: {op_name}")

    return results

# Unit tests
def test_string_operations():
    # Test slice operation
    assert string_operations("hello", [("slice", 1, 4)]) == ["ell"]
    assert string_operations("hello", [("slice", 0, 10)]) == ["hello"]
    assert string_operations("hello", [("slice", 5, 10)]) == [""]

    # Test check operation
    assert string_operations("hello", [("check", "ell")]) == [True]
    assert string_operations("hello", [("check", "world")]) == [False]

    # Test concat operation
    assert string_operations("hello", [("concat", " world")]) == ["hello world"]
    assert string_operations("", [("concat", "world")]) == ["world"]

    # Test format operation
    assert string_operations("Hello, {}!", [("format", ["World"])]) == ["Hello, World!"]
    assert string_operations("Numbers: {}, {}", [("format", [1, 2])]) == ["Numbers: 1, 2"]

    # Test invalid operations
    try:
        string_operations("hello", [("invalid",)])
    except ValueError as e:
        assert str(e) == "Unsupported operation: invalid"

    try:
        string_operations("hello {}", [("format", ["only one"])])
    except ValueError as e:
        assert str(e) == "The number of placeholders does not match the number of values provided."

    print("All tests passed.")

# Run tests
test_string_operations()
