```python
import pygame
import sys
import numpy as np

# Constants
CELL_SIZE = 20
GRID_WIDTH = 30
GRID_HEIGHT = 20
FPS = 10

# Colors
WHITE = (255, 255, 255)
BLACK = (0, 0, 0)
GRAY = (200, 200, 200)

# Initialize Pygame
pygame.init()
screen = pygame.display.set_mode((GRID_WIDTH * CELL_SIZE, GRID_HEIGHT * CELL_SIZE))
pygame.display.set_caption("Conway's Game of Life")
clock = pygame.time.Clock()

def initialize_grid():
    return np.zeros((GRID_HEIGHT, GRID_WIDTH), dtype=int)

def draw_grid(grid):
    for y in range(GRID_HEIGHT):
        for x in range(GRID_WIDTH):
            rect = pygame.Rect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE)
            color = WHITE if grid[y, x] == 1 else BLACK
            pygame.draw.rect(screen, color, rect)
            pygame.draw.rect(screen, GRAY, rect, 1)

def toggle_cell(grid, pos):
    x, y = pos[0] // CELL_SIZE, pos[1] // CELL_SIZE
    if 0 <= x < GRID_WIDTH and 0 <= y < GRID_HEIGHT:
        grid[y, x] = 1 - grid[y, x]

def update_grid(grid):
    new_grid = grid.copy()
    for y in range(GRID_HEIGHT):
        for x in range(GRID_WIDTH):
            alive_neighbors = np.sum(grid[max(0, y-1):min(GRID_HEIGHT, y+2), max(0, x-1):min(GRID_WIDTH, x+2)]) - grid[y, x]
            if grid[y, x] == 1 and (alive_neighbors < 2 or alive_neighbors > 3):
                new_grid[y, x] = 0
            elif grid[y, x] == 0 and alive_neighbors == 3:
                new_grid[y, x] = 1
    return new_grid

def main_menu():
    font = pygame.font.Font(None, 36)
    options = ["Configure Cells Manually", "Start the Game"]
    selected = 0

    while True:
        screen.fill(BLACK)
        for i, option in enumerate(options):
            color = WHITE if i == selected else GRAY
            text = font.render(option, True, color)
            screen.blit(text, (50, 50 + i * 40))

        pygame.display.flip()

        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_DOWN:
                    selected = (selected + 1) % len(options)
                elif event.key == pygame.K_UP:
                    selected = (selected - 1) % len(options)
                elif event.key == pygame.K_RETURN:
                    return selected

def configure_cells(grid):
    while True:
        draw_grid(grid)
        pygame.display.flip()

        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            elif event.type == pygame.MOUSEBUTTONDOWN:
                toggle_cell(grid, event.pos)
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_RETURN:
                    return

def run_game(grid):
    while True:
        draw_grid(grid)
        pygame.display.flip()
        grid = update_grid(grid)
        clock.tick(FPS)

        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()

def test_update_grid():
    initial_grid = np.array([
        [0, 1, 0],
        [0, 1, 0],
        [0, 1, 0]
    ])
    expected_grid = np.array([
        [0, 0, 0],
        [1, 1, 1],
        [0, 0, 0]
    ])
    assert np.array_equal(update_grid(initial_grid), expected_grid), "Test failed!"

if __name__ == "__main__":
    test_update_grid()
    grid = initialize_grid()
    while True:
        choice = main_menu()
        if choice == 0:
            configure_cells(grid)
        elif choice == 1:
            run_game(grid)
```

### Explanation:

1. **Grid Initialization**: The grid is initialized as a 2D NumPy array filled with zeros, representing dead cells.

2. **Drawing the Grid**: The `draw_grid` function iterates over each cell, drawing it as either white (alive) or black (dead), with gray lines for the grid.

3. **Toggle Cell State**: The `toggle_cell` function changes the state of a cell when clicked, ensuring clicks outside the grid are ignored.

4. **Grid Update Logic**: The `update_grid` function applies the rules of Conway's Game of Life to update the grid state.

5. **Main Menu**: The `main_menu` function allows the user to select between configuring cells manually or starting the game.

6. **Configure Cells**: The `configure_cells` function lets the user toggle cell states before starting the simulation.

7. **Run Game**: The `run_game` function continuously updates the grid at a specified FPS, applying the Game of Life rules.

8. **Unit Test**: The `test_update_grid` function verifies the correctness of the grid update logic.

