```python
class QMapError(Exception):
    """Custom exception for invalid job status."""
    pass

class JobStatus:
    COMPLETED = "COMPLETED"
    UNSUBMITTED = "UNSUBMITTED"
    RUNNING = "RUNNING"
    PENDING = "PENDING"
    FAILED = "FAILED"
    OTHER = "OTHER"

    @classmethod
    def all_statuses(cls):
        return [cls.COMPLETED, cls.UNSUBMITTED, cls.RUNNING, cls.PENDING, cls.FAILED]

    @classmethod
    def abbreviation_map(cls):
        return {
            'c': cls.COMPLETED,
            'u': cls.UNSUBMITTED,
            'r': cls.RUNNING,
            'p': cls.PENDING,
            'f': cls.FAILED
        }

def parse_status(status_codes):
    valid_statuses = JobStatus.all_statuses()
    abbreviation_map = JobStatus.abbreviation_map()

    if 'all' in status_codes or 'a' in status_codes:
        return valid_statuses

    normalized_statuses = []
    for code in status_codes:
        if code in valid_statuses:
            normalized_statuses.append(code)
        elif code in abbreviation_map:
            normalized_statuses.append(abbreviation_map[code])
        else:
            raise QMapError(f"Invalid status code: {code}")

    return normalized_statuses

# Test cases
def test_parse_status():
    try:
        # Test case 1: 'all' keyword
        assert parse_status(['all']) == JobStatus.all_statuses()

        # Test case 2: 'a' abbreviation
        assert parse_status(['a']) == JobStatus.all_statuses()

        # Test case 3: Full status strings
        assert parse_status(['COMPLETED', 'RUNNING']) == ['COMPLETED', 'RUNNING']

        # Test case 4: Single-letter abbreviations
        assert parse_status(['c', 'r']) == ['COMPLETED', 'RUNNING']

        # Test case 5: Mixed valid inputs
        assert parse_status(['COMPLETED', 'r', 'PENDING']) == ['COMPLETED', 'RUNNING', 'PENDING']

        # Test case 6: Invalid status code
        try:
            parse_status(['INVALID'])
            assert False, "Expected QMapError"
        except QMapError as e:
            assert str(e) == "Invalid status code: INVALID"

        # Test case 7: Invalid abbreviation
        try:
            parse_status(['x'])
            assert False, "Expected QMapError"
        except QMapError as e:
            assert str(e) == "Invalid status code: x"

        print("All test cases passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")

# Run test cases
test_parse_status()
