    time_string = "2021-01-01_00:00:00"
    print(to_epoch(time_string))  # Expected output: 1609459200

    # Test today_stamps
    start_of_day, end_of_day = today_stamps()
    print(start_of_day, end_of_day)  # Outputs may vary depending on the current day

    # Test fix_id
