import time
import datetime
import logging

# Configure logging
logging.basicConfig(level=logging.DEBUG)
logger = logging.getLogger(__name__)

class NoDevice(Exception):
    """Custom exception raised when no device data is available."""
    pass

def unix_to_human_readable(unix_timestamp, separator='-'):
    """Convert a Unix timestamp string to a human-readable time string with a custom separator."""
    try:
        timestamp = int(unix_timestamp)
        dt = datetime.datetime.fromtimestamp(timestamp)
        return dt.strftime(f'%Y{separator}%m{separator}%d %H:%M:%S')
    except (ValueError, TypeError) as e:
        logger.debug(f"Error converting Unix timestamp to human-readable: {e}")
        raise

def human_readable_to_unix(human_time, separator='-'):
    """Convert a human-readable time string with a custom separator to a Unix epoch timestamp."""
    try:
        dt = datetime.datetime.strptime(human_time, f'%Y{separator}%m{separator}%d %H:%M:%S')
        return int(dt.timestamp())
    except (ValueError, TypeError) as e:
        logger.debug(f"Error converting human-readable time to Unix timestamp: {e}")
        raise

def get_start_end_of_day():
    """Calculate the Unix timestamps for the start and end of the current day."""
    now = datetime.datetime.now()
    start_of_day = datetime.datetime(now.year, now.month, now.day, 0, 0, 0)
    end_of_day = datetime.datetime(now.year, now.month, now.day, 23, 59, 59)
    return int(start_of_day.timestamp()), int(end_of_day.timestamp())

def clean_device_ids(raw_data):
    """Clean up device and module IDs in the raw data by removing any superfluous spaces."""
    if not isinstance(raw_data, dict):
        logger.debug("Raw data is not a dictionary.")
        raise ValueError("Raw data must be a dictionary.")

    cleaned_data = {}
    for key, value in raw_data.items():
        if isinstance(value, str):
            cleaned_data[key] = value.strip()
        else:
            cleaned_data[key] = value
    return cleaned_data

def extract_data_from_response(response):
    """Extract raw data from a server response, handling different tags and potential errors."""
    if not isinstance(response, dict):
        logger.debug("Response is not a dictionary.")
        raise ValueError("Response must be a dictionary.")

    try:
        data = response.get('data', {})
        if not data:
            logger.debug("No data found in the response.")
            raise NoDevice("No device data available in the response.")

        errors = response.get('errors', [])
        if errors:
            logger.debug(f"Errors found in the response: {errors}")
            raise NoDevice(f"Errors in response: {errors}")

        return {'data': data, 'errors': errors}
    except KeyError as e:
        logger.debug(f"Key error when extracting data from response: {e}")
        raise NoDevice("Error extracting device data from response.")

# Example usage
if __name__ == "__main__":
    # Example usage of the module functions
    unix_time = "1638316800"
    human_time = "2021-12-01 00:00:00"

    print(unix_to_human_readable(unix_time))
    print(human_readable_to_unix(human_time))
    print(get_start_end_of_day())

    raw_data = {'device_id': ' 12345 ', 'module_id': ' 67890 '}
    print(clean_device_ids(raw_data))

    response = {'data': {'device_id': '12345'}, 'errors': []}
    print(extract_data_from_response(response))
