print(min_elements_to_remove([2, 4, 6, 8, 10]))  # Should return (1, [1])
print(min_elements_to_remove([1, 2, 3, 4, 5, 6]))  # Should return (1, [1])
print(min_elements_to_remove([10, 12, 14, 16]))  # Should return (-1, [])
