def get_primes(n):
    """Generate a list of prime numbers up to n using the Sieve of Eratosthenes."""
    if n < 2:
        return []
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for start in range(2, int(n**0.5) + 1):
        if sieve[start]:
            for i in range(start*start, n + 1, start):
                sieve[i] = False
    return [num for num, is_prime in enumerate(sieve) if is_prime]

def is_prime(num, primes):
    """Check if a number is prime using a list of known primes."""
    if num < 2:
        return False
    for prime in primes:
        if prime * prime > num:
            break
        if num % prime == 0:
            return False
    return True

def min_elements_to_remove(data):
    """Determine the minimum number of elements to remove to make the sum of the remaining elements a prime number."""
    total_sum = sum(data)
    max_possible_prime = total_sum
    primes = get_primes(max_possible_prime)

    if is_prime(total_sum, primes):
        return (0, [])

    n = len(data)
    for num_to_remove in range(1, n + 1):
        for indices in combinations(range(n), num_to_remove):
            remaining_sum = total_sum - sum(data[i] for i in indices)
            if is_prime(remaining_sum, primes):
                return (num_to_remove, [i + 1 for i in indices])

    return (-1, [])

from itertools import combinations

# Unit tests
