import unittest
import subprocess
import os
import toml

class TestPulpCLI(unittest.TestCase):

    def setUp(self):
        self.test_file = 'test_config.toml'
        if os.path.exists(self.test_file):
            os.remove(self.test_file)

    def tearDown(self):
        if os.path.exists(self.test_file):
            os.remove(self.test_file)

    def test_create_default(self):
        result = subprocess.run(['python', 'pulp_cli.py', 'create', '--file', self.test_file], capture_output=True, text=True)
        self.assertIn('Configuration file test_config.toml created successfully.', result.stdout)
        self.assertTrue(os.path.exists(self.test_file))
        with open(self.test_file, 'r') as f:
            config = toml.load(f)
        self.assertEqual(config['base_url'], 'http://localhost')

    def test_create_overwrite(self):
        subprocess.run(['python', 'pulp_cli.py', 'create', '--file', self.test_file], capture_output=True, text=True)
        result = subprocess.run(['python', 'pulp_cli.py', 'create', '--file', self.test_file, '--overwrite'], capture_output=True, text=True)
        self.assertIn('Configuration file test_config.toml created successfully.', result.stdout)

    def test_validate_valid(self):
        subprocess.run(['python', 'pulp_cli.py', 'create', '--file', self.test_file], capture_output=True, text=True)
        result = subprocess.run(['python', 'pulp_cli.py', 'validate', '--file', self.test_file], capture_output=True, text=True)
        self.assertIn('Configuration file is valid.', result.stdout)

    def test_validate_invalid(self):
        with open(self.test_file, 'w') as f:
            f.write("invalid_toml")
        result = subprocess.run(['python', 'pulp_cli.py', 'validate', '--file', self.test_file], capture_output=True, text=True)
        self.assertIn('Invalid TOML format', result.stdout)

if __name__ == '__main__':
    unittest.main()
