import random

def scramble_word(word):
    """Scramble the characters of the word ensuring no character remains in the same index."""
    if len(word) <= 1:
        return word

    scrambled = list(word)
    while True:
        random.shuffle(scrambled)
        if all(scrambled[i] != word[i] for i in range(len(word))):
            break
    return ''.join(scrambled)

def generate_password(input_phrase):
    """Generate a scrambled password from the input phrase."""
    words = input_phrase.split()
    scrambled_words = [scramble_word(word) for word in words]
    return ' '.join(scrambled_words)

def main():
    print("Welcome to the Random Password Generator!")
    print("Instructions:")
    print("1. Enter a word or phrase to generate a scrambled password.")
    print("2. The generated password will not have any character in the same position as the input.")
    print("3. You can generate multiple passwords or exit the program when you're done.")

    while True:
        try:
            user_input = input("\nEnter a word or phrase for password generation (or type 'exit' to quit): ").strip()
            if user_input.lower() == 'exit':
                print("Exiting the program. Goodbye!")
                break
            if not user_input:
                raise ValueError("Input cannot be empty. Please enter a valid word or phrase.")

            password = generate_password(user_input)
            print(f"Generated Password: {password}")

        except ValueError as ve:
            print(f"Error: {ve}")

if __name__ == "__main__":
    main()
