To create an AWS Lambda function that processes S3 object creation events using AWS Lambda Powertools for logging, tracing, and metrics, follow the steps below. This function will handle S3 object retrieval, log the content, and record a custom metric. It will also include unit tests to verify its functionality.

### Lambda Function Code

```python
import json
import boto3
from botocore.exceptions import ClientError
from aws_lambda_powertools import Logger, Tracer, Metrics
from aws_lambda_powertools.metrics import MetricUnit

# Initialize AWS Lambda Powertools utilities
logger = Logger()
tracer = Tracer()
metrics = Metrics()

s3_client = boto3.client('s3')

@metrics.log_metrics(capture_cold_start_metric=True)
@tracer.capture_lambda_handler
@logger.inject_lambda_context
def lambda_handler(event, context):
    logger.info("Received event: %s", json.dumps(event))

    try:
        # Extract bucket name and object key from the event
        bucket_name = event['Records'][0]['s3']['bucket']['name']
        object_key = event['Records'][0]['s3']['object']['key']

        # Retrieve the S3 object
        response = s3_client.get_object(Bucket=bucket_name, Key=object_key)
        content = response['Body'].read().decode('utf-8')

        # Log the content of the S3 object
        logger.debug("S3 Object Content: %s", content)

        # Record a custom metric
        metrics.add_metric(name="S3ObjectProcessed", unit=MetricUnit.Count, value=1)

        return {
            "statusCode": 200,
            "body": {
                "message": "S3 object processed successfully",
                "content": content,
                "bucket": bucket_name,
                "key": object_key
            }
        }

    except ClientError as e:
        logger.error("Error retrieving S3 object: %s", e)
        return {
            "statusCode": 500,
            "body": {
                "message": "Error retrieving S3 object",
                "error": str(e)
            }
        }
    except UnicodeDecodeError as e:
        logger.error("Error decoding S3 object content: %s", e)
        return {
            "statusCode": 500,
            "body": {
                "message": "Error decoding S3 object content",
                "error": str(e)
            }
        }
    except Exception as e:
        logger.error("Unexpected error: %s", e)
        return {
            "statusCode": 500,
            "body": {
                "message": "Unexpected error",
                "error": str(e)
            }
        }
```

