import unittest
from unittest.mock import patch, MagicMock
from lambda_function import lambda_handler

class TestLambdaFunction(unittest.TestCase):

    @patch('lambda_function.s3_client')
    def test_lambda_handler_success(self, mock_s3_client):
        # Mock S3 get_object response
        mock_s3_client.get_object.return_value = {
            'Body': MagicMock(read=MagicMock(return_value=b'Hello, World!'))
        }

        # Create a sample S3 event
        event = {
            'Records': [{
                's3': {
                    'bucket': {'name': 'test-bucket'},
                    'object': {'key': 'test-key'}
                }
            }]
        }

        # Call the lambda_handler function
        response = lambda_handler(event, None)

        # Assert the response
        self.assertEqual(response['statusCode'], 200)
        self.assertIn('Hello, World!', response['body']['content'])

    @patch('lambda_function.s3_client')
    def test_lambda_handler_object_not_found(self, mock_s3_client):
        # Mock S3 get_object to raise a ClientError
        mock_s3_client.get_object.side_effect = ClientError(
            {"Error": {"Code": "NoSuchKey", "Message": "The specified key does not exist."}},
            "GetObject"
        )

        # Create a sample S3 event
        event = {
            'Records': [{
                's3': {
                    'bucket': {'name': 'test-bucket'},
                    'object': {'key': 'non-existent-key'}
                }
            }]
        }

        # Call the lambda_handler function
        response = lambda_handler(event, None)

        # Assert the response
        self.assertEqual(response['statusCode'], 500)
        self.assertIn('Error retrieving S3 object', response['body']['message'])

    @patch('lambda_function.s3_client')
    def test_lambda_handler_decoding_error(self, mock_s3_client):
        # Mock S3 get_object response with non-UTF-8 content
        mock_s3_client.get_object.return_value = {
            'Body': MagicMock(read=MagicMock(return_value=b'\x80\x81\x82'))
        }

        # Create a sample S3 event
        event = {
            'Records': [{
                's3': {
                    'bucket': {'name': 'test-bucket'},
                    'object': {'key': 'test-key'}
                }
            }]
        }

        # Call the lambda_handler function
        response = lambda_handler(event, None)

        # Assert the response
        self.assertEqual(response['statusCode'], 500)
        self.assertIn('Error decoding S3 object content', response['body']['message'])

if __name__ == '__main__':
    unittest.main()
