def is_prime(number):
    """Check if a number is a prime number."""
    if number <= 1:
        return False
    if number <= 3:
        return True
    if number % 2 == 0 or number % 3 == 0:
        return False
    i = 5
    while i * i <= number:
        if number % i == 0 or number % (i + 2) == 0:
            return False
        i += 6
    return True

def get_valid_input(prompt):
    """Prompt the user for a valid integer greater than 1."""
    while True:
        try:
            value = int(input(prompt))
            if value > 1:
                return value
            else:
                print("Please enter an integer greater than 1.")
        except ValueError:
            print("Invalid input. Please enter an integer.")

def find_primes_in_range(start, end):
    """Find and print all prime numbers in the given range."""
    for num in range(start, end + 1):
        if is_prime(num):
            print(num)

def main():
    print("Find all prime numbers in a given range.")
    start = get_valid_input("Enter the start of the range (integer > 1): ")
    end = get_valid_input("Enter the end of the range (integer > 1): ")

    if start > end:
        print("The start of the range should be less than or equal to the end. Swapping values.")
        start, end = end, start

    print(f"Prime numbers between {start} and {end} are:")
    find_primes_in_range(start, end)

if __name__ == "__main__":
    main()
```

### Explanation:

1. **`is_prime(number)`**: This function checks if a given number is prime. It handles small numbers directly and uses a loop to check divisibility for larger numbers, optimizing by checking up to the square root of the number.

2. **`get_valid_input(prompt)`**: This function repeatedly prompts the user for input until a valid integer greater than 1 is entered.

3. **`find_primes_in_range(start, end)`**: This function iterates over the range from `start` to `end` (inclusive) and prints each number if it is prime.

4. **`main()`**: This function orchestrates the input gathering and prime number finding. It also ensures that the start of the range is less than or equal to the end, swapping them if necessary.

This program will prompt the user for input, validate it, and then print each prime number in the specified range on a new line.

