To design a Python class that represents a simplified financial transaction protocol, we can create a class called `FinancialTransactionProtocol`. This class will handle the creation and validation of `Transaction` and `Confirmation` messages. We'll use Python's `dataclasses` module to simplify the creation of these message types. Here's how you can implement this:

```python
from dataclasses import dataclass
import uuid

@dataclass
class Transaction:
    sender: str
    receiver: str
    amount: float
    currency: str
    transaction_id: str

    def __post_init__(self):
        if self.amount < 0:
            raise ValueError("Amount must be non-negative.")
        if not self.transaction_id:
            raise ValueError("Transaction ID must be provided.")

@dataclass
class Confirmation:
    transaction_id: str
    success: bool

    def __post_init__(self):
        if not self.transaction_id:
            raise ValueError("Transaction ID must be provided.")

class FinancialTransactionProtocol:
    def __init__(self):
        self.transactions = {}

    def create_transaction(self, sender, receiver, amount, currency):
        transaction_id = str(uuid.uuid4())
        transaction = Transaction(sender, receiver, amount, currency, transaction_id)
        self.transactions[transaction_id] = transaction
        return transaction

    def create_confirmation(self, transaction_id, success):
        if transaction_id not in self.transactions:
            raise ValueError("Transaction ID does not exist.")
        confirmation = Confirmation(transaction_id, success)
        return confirmation

    def is_transaction_valid(self, transaction):
        if not isinstance(transaction, Transaction):
            return False
        if transaction.amount < 0:
            return False
        if not transaction.transaction_id:
            return False
        return True

    def is_confirmation_valid(self, confirmation):
        if not isinstance(confirmation, Confirmation):
            return False
        if confirmation.transaction_id not in self.transactions:
            return False
        return True

    def get_transaction(self, transaction_id):
        return self.transactions.get(transaction_id)

    def get_confirmation_details(self, confirmation):
        return {
            "transaction_id": confirmation.transaction_id,
            "success": confirmation.success
        }

# Example usage:
protocol = FinancialTransactionProtocol()
transaction = protocol.create_transaction("Alice", "Bob", 100.0, "USD")
print(protocol.is_transaction_valid(transaction))  # True

confirmation = protocol.create_confirmation(transaction.transaction_id, True)
print(protocol.is_confirmation_valid(confirmation))  # True

print(protocol.get_transaction(transaction.transaction_id))
print(protocol.get_confirmation_details(confirmation))
```

