### Step 6: Write Unit Tests

Create unit tests to verify the functionality of the serializers and views.

```python
from django.test import TestCase
from rest_framework.test import APIClient
from rest_framework import status
from .models import City, Kind, SocialAccount
from .serializers import CitySerializer, KindSerializer, SocialAccountSerializer

class SocialAccountAPITestCase(TestCase):
    def setUp(self):
        self.client = APIClient()
        self.city = City.objects.create(name='New York')
        self.kind = Kind.objects.create(type='Facebook')
        self.social_account = SocialAccount.objects.create(
            unique_identifier='12345',
            style_class='social-class',
            city=self.city,
            kind=self.kind
        )

    def test_create_social_account(self):
        data = {
            'unique_identifier': '67890',
            'style_class': 'new-class',
            'city': {'name': 'Los Angeles'},
            'kind': {'type': 'Twitter'}
        }
        response = self.client.post('/socialaccounts/', data, format='json')
        self.assertEqual(response.status_code, status.HTTP_201_CREATED)

    def test_retrieve_social_account(self):
        response = self.client.get(f'/socialaccounts/{self.social_account.id}/')
        self.assertEqual(response.status_code, status.HTTP_200_OK)

    def test_update_social_account(self):
        data = {
            'unique_identifier': '12345',
            'style_class': 'updated-class',
            'city': {'name': 'New York'},
            'kind': {'type': 'Facebook'}
        }
        response = self.client.put(f'/socialaccounts/{self.social_account.id}/', data, format='json')
        self.assertEqual(response.status_code, status.HTTP_200_OK)

    def test_delete_social_account(self):
        response = self.client.delete(f'/socialaccounts/{self.social_account.id}/')
        self.assertEqual(response.status_code, status.HTTP_204_NO_CONTENT)
