To implement a reinforcement learning agent that operates in a classification environment, we'll define several classes: `Agent`, `ValueAgent`, `PolicyAgent`, and `ReplayBuffer`. Each agent will have a `step` method to interact with the environment and store experiences in the replay buffer. We'll also include unit tests to verify the functionality of each component.

Here's a detailed implementation:

### Environment and Transition

First, let's define the `ClassifyEnv` and `Transition` data structure:

```python
import numpy as np
from collections import namedtuple

# Define a named tuple for storing experiences
Transition = namedtuple('Transition', ('state', 'action', 'reward', 'next_state', 'done'))

class ClassifyEnv:
    def __init__(self, num_actions):
        self.num_actions = num_actions
        self.current_state = self.reset()

    def reset(self):
        # Reset the environment to an initial state
        self.current_state = (np.random.randint(0, 100), np.random.randint(0, 100))
        return self.current_state

    def step(self, action):
        # Simulate taking an action in the environment
        next_state = (np.random.randint(0, 100), np.random.randint(0, 100))
        reward = np.random.rand()
        done = np.random.choice([True, False])
        return next_state, reward, done
```

### Replay Buffer

```python
import random

class ReplayBuffer:
    def __init__(self, capacity):
        self.capacity = capacity
        self.buffer = []
        self.position = 0

    def push(self, *args):
        """Save a transition."""
        if len(self.buffer) < self.capacity:
            self.buffer.append(None)
        self.buffer[self.position] = Transition(*args)
        self.position = (self.position + 1) % self.capacity

    def sample(self, batch_size):
        return random.sample(self.buffer, batch_size)

    def __len__(self):
        return len(self.buffer)
```

### Agent Classes

#### Base Agent

```python
class Agent:
    def __init__(self, action_space):
        self.action_space = action_space

    def select_action(self, state):
        return 0  # Always return action 0

    def step(self, env, replay_buffer):
        state = env.current_state
        action = self.select_action(state)
        next_state, reward, done = env.step(action)
        replay_buffer.push(state, action, reward, next_state, done)
        return reward, done
```

#### Value Agent

```python
import torch
import torch.nn as nn
import torch.nn.functional as F

class QNetwork(nn.Module):
    def __init__(self, input_dim, output_dim):
        super(QNetwork, self).__init__()
        self.fc1 = nn.Linear(input_dim, 128)
        self.fc2 = nn.Linear(128, output_dim)

    def forward(self, x):
        x = F.relu(self.fc1(x))
        return self.fc2(x)

class ValueAgent(Agent):
    def __init__(self, action_space, q_network, epsilon=0.1):
        super().__init__(action_space)
        self.q_network = q_network
        self.epsilon = epsilon

    def select_action(self, state):
        if np.random.rand() < self.epsilon:
            return np.random.choice(self.action_space)
        else:
            with torch.no_grad():
                state_tensor = torch.tensor(state, dtype=torch.float32)
                q_values = self.q_network(state_tensor)
                return q_values.argmax().item()
```

#### Policy Agent

```python
class PolicyNetwork(nn.Module):
    def __init__(self, input_dim, output_dim):
        super(PolicyNetwork, self).__init__()
        self.fc1 = nn.Linear(input_dim, 128)
        self.fc2 = nn.Linear(128, output_dim)

    def forward(self, x):
        x = F.relu(self.fc1(x))
        return F.softmax(self.fc2(x), dim=-1)

class PolicyAgent(Agent):
    def __init__(self, action_space, policy_network):
        super().__init__(action_space)
        self.policy_network = policy_network

    def select_action(self, state):
        with torch.no_grad():
            state_tensor = torch.tensor(state, dtype=torch.float32)
            action_probs = self.policy_network(state_tensor)
            action = np.random.choice(self.action_space, p=action_probs.numpy())
            return action
```

