import unittest

class TestAgents(unittest.TestCase):
    def setUp(self):
        self.env = ClassifyEnv(num_actions=3)
        self.replay_buffer = ReplayBuffer(capacity=100)

    def test_agent(self):
        agent = Agent(action_space=3)
        reward, done = agent.step(self.env, self.replay_buffer)
        self.assertEqual(len(self.replay_buffer), 1)
        self.assertEqual(self.replay_buffer.buffer[0].action, 0)

    def test_value_agent(self):
        q_network = QNetwork(input_dim=2, output_dim=3)
        agent = ValueAgent(action_space=3, q_network=q_network, epsilon=0.1)
        reward, done = agent.step(self.env, self.replay_buffer)
        self.assertEqual(len(self.replay_buffer), 1)

    def test_policy_agent(self):
        policy_network = PolicyNetwork(input_dim=2, output_dim=3)
        agent = PolicyAgent(action_space=3, policy_network=policy_network)
        reward, done = agent.step(self.env, self.replay_buffer)
        self.assertEqual(len(self.replay_buffer), 1)

if __name__ == '__main__':
    unittest.main()
```

