To create a Python Flask application for a user management system with the specified endpoints and functionalities, we will structure the application using blueprints. This will help organize the code and make it more maintainable. We'll also include placeholder functions to simulate the intended behavior of each endpoint. Additionally, we'll use Flask's built-in testing capabilities to write unit tests for each endpoint.

Here's the complete code for the Flask application:

```python
from flask import Flask, Blueprint, request, jsonify
from werkzeug.security import generate_password_hash, check_password_hash
import uuid

app = Flask(__name__)

# Simulated database
users_db = {}

# Blueprint for authentication routes
auth_bp = Blueprint('auth', __name__, url_prefix='/auth')

@auth_bp.route('/register', methods=['POST'])
def register():
    data = request.json
    username = data.get('username')
    email = data.get('email')
    password = data.get('password')

    if not username or not email or not password:
        return jsonify({'message': 'Invalid input'}), 400

    if email in users_db:
        return jsonify({'message': 'User already exists'}), 400

    hashed_password = generate_password_hash(password)
    user_id = str(uuid.uuid4())
    users_db[email] = {'id': user_id, 'username': username, 'email': email, 'password': hashed_password}

    return jsonify({'message': 'User registered successfully'}), 201

@auth_bp.route('/login', methods=['POST'])
def login():
    data = request.json
    email = data.get('email')
    password = data.get('password')

    user = users_db.get(email)
    if user and check_password_hash(user['password'], password):
        # Simulate token generation
        token = str(uuid.uuid4())
        return jsonify({'message': 'Login successful', 'token': token}), 200

    return jsonify({'message': 'Invalid credentials'}), 401

@auth_bp.route('/logout', methods=['POST'])
def logout():
    # Simulate token invalidation
    return jsonify({'message': 'Logout successful'}), 200

@auth_bp.route('/refresh', methods=['POST'])
def refresh():
    # Simulate token refresh
    new_token = str(uuid.uuid4())
    return jsonify({'message': 'Token refreshed', 'token': new_token}), 200

# Blueprint for user routes
user_bp = Blueprint('user', __name__, url_prefix='/user')

@user_bp.route('/all', methods=['GET'])
def get_all_users():
    users = [{'id': user['id'], 'username': user['username'], 'email': user['email']} for user in users_db.values()]
    return jsonify(users), 200

@user_bp.route('/<user_id>', methods=['GET'])
def get_user(user_id):
    for user in users_db.values():
        if user['id'] == user_id:
            return jsonify({'id': user['id'], 'username': user['username'], 'email': user['email']}), 200
    return jsonify({'message': 'User not found'}), 404

@user_bp.route('/update-password', methods=['POST'])
def update_password():
    data = request.json
    email = data.get('email')
    new_password = data.get('new_password')

    user = users_db.get(email)
    if user:
        user['password'] = generate_password_hash(new_password)
        return jsonify({'message': 'Password updated successfully'}), 200

    return jsonify({'message': 'User not found'}), 404

# Register blueprints
app.register_blueprint(auth_bp)
app.register_blueprint(user_bp)

if __name__ == '__main__':
    app.run(debug=True)
```

