To create a Python module that provides utilities for creating various types of cyber threat intelligence observables compliant with the STIX 2.0 standard, we need to define a structure that includes validation, creation, and testing of observables. Below is a detailed implementation of such a module:

```python
from typing import NamedTuple, List, Dict, Any
import re
import unittest

# Define a NamedTuple for observable properties
class ObservableProperties(NamedTuple):
    value: str
    creator_identity: str
    labels: List[str]
    marking_definitions: List[str]

# Helper function to generate default custom properties
def generate_default_properties() -> Dict[str, Any]:
    return {
        "score": 0,
        "labels": [],
        "marking_definitions": [],
    }

# Validation functions
def validate_ipv4(value: str) -> bool:
    pattern = r"^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$"
    return re.match(pattern, value) is not None

def validate_ipv6(value: str) -> bool:
    pattern = r"^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$"
    return re.match(pattern, value) is not None

def validate_domain(value: str) -> bool:
    pattern = r"^(?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}$"
    return re.match(pattern, value) is not None

def validate_hostname(value: str) -> bool:
    pattern = r"^(?:[a-zA-Z0-9-]+\.)+[a-zA-Z0-9-]+$"
    return re.match(pattern, value) is not None

def validate_url(value: str) -> bool:
    pattern = r"^(https?|ftp)://[^\s/$.?#].[^\s]*$"
    return re.match(pattern, value) is not None

def validate_file_hash(value: str, hash_type: str) -> bool:
    patterns = {
        "md5": r"^[a-fA-F0-9]{32}$",
        "sha1": r"^[a-fA-F0-9]{40}$",
        "sha256": r"^[a-fA-F0-9]{64}$",
    }
    return re.match(patterns[hash_type], value) is not None

# Observable creation functions
def create_ipv4_observable(properties: ObservableProperties) -> Dict[str, Any]:
    """Create an IPv4 Address observable."""
    if not validate_ipv4(properties.value):
        raise ValueError("Invalid IPv4 address format.")
    return {
        "type": "ipv4-addr",
        "value": properties.value,
        "creator_identity": properties.creator_identity,
        "labels": properties.labels,
        "marking_definitions": properties.marking_definitions,
    }

def create_ipv6_observable(properties: ObservableProperties) -> Dict[str, Any]:
    """Create an IPv6 Address observable."""
    if not validate_ipv6(properties.value):
        raise ValueError("Invalid IPv6 address format.")
    return {
        "type": "ipv6-addr",
        "value": properties.value,
        "creator_identity": properties.creator_identity,
        "labels": properties.labels,
        "marking_definitions": properties.marking_definitions,
    }

def create_domain_observable(properties: ObservableProperties) -> Dict[str, Any]:
    """Create a Domain Name observable."""
    if not validate_domain(properties.value):
        raise ValueError("Invalid domain name format.")
    return {
        "type": "domain-name",
        "value": properties.value,
        "creator_identity": properties.creator_identity,
        "labels": properties.labels,
        "marking_definitions": properties.marking_definitions,
    }

def create_hostname_observable(properties: ObservableProperties) -> Dict[str, Any]:
    """Create a Hostname observable."""
    if not validate_hostname(properties.value):
        raise ValueError("Invalid hostname format.")
    return {
        "type": "hostname",
        "value": properties.value,
        "creator_identity": properties.creator_identity,
        "labels": properties.labels,
        "marking_definitions": properties.marking_definitions,
    }

def create_url_observable(properties: ObservableProperties) -> Dict[str, Any]:
    """Create a URL observable."""
    if not validate_url(properties.value):
        raise ValueError("Invalid URL format.")
    return {
        "type": "url",
        "value": properties.value,
        "creator_identity": properties.creator_identity,
        "labels": properties.labels,
        "marking_definitions": properties.marking_definitions,
    }

def create_file_observable(properties: ObservableProperties, md5: str = "", sha1: str = "", sha256: str = "") -> Dict[str, Any]:
    """Create a File observable with optional hashes."""
    if md5 and not validate_file_hash(md5, "md5"):
        raise ValueError("Invalid MD5 hash format.")
    if sha1 and not validate_file_hash(sha1, "sha1"):
        raise ValueError("Invalid SHA-1 hash format.")
    if sha256 and not validate_file_hash(sha256, "sha256"):
        raise ValueError("Invalid SHA-256 hash format.")
    return {
        "type": "file",
        "name": properties.value,
        "hashes": {
            "MD5": md5,
            "SHA-1": sha1,
            "SHA-256": sha256,
        },
        "creator_identity": properties.creator_identity,
        "labels": properties.labels,
        "marking_definitions": properties.marking_definitions,
    }

# Unit tests
class TestObservables(unittest.TestCase):

    def test_ipv4_observable(self):
        props = ObservableProperties(value="192.168.1.1", creator_identity="test-creator", labels=["malicious"], marking_definitions=["TLP:WHITE"])
        observable = create_ipv4_observable(props)
        self.assertEqual(observable["type"], "ipv4-addr")
        self.assertEqual(observable["value"], "192.168.1.1")

    def test_invalid_ipv4_observable(self):
        props = ObservableProperties(value="999.999.999.999", creator_identity="test-creator", labels=["malicious"], marking_definitions=["TLP:WHITE"])
        with self.assertRaises(ValueError):
            create_ipv4_observable(props)

    def test_domain_observable(self):
        props = ObservableProperties(value="example.com", creator_identity="test-creator", labels=["benign"], marking_definitions=["TLP:GREEN"])
        observable = create_domain_observable(props)
        self.assertEqual(observable["type"], "domain-name")
        self.assertEqual(observable["value"], "example.com")

    def test_invalid_domain_observable(self):
        props = ObservableProperties(value="invalid_domain", creator_identity="test-creator", labels=["benign"], marking_definitions=["TLP:GREEN"])
        with self.assertRaises(ValueError):
            create_domain_observable(props)

    def test_file_observable(self):
        props = ObservableProperties(value="malware.exe", creator_identity="test-creator", labels=["malicious"], marking_definitions=["TLP:RED"])
        observable = create_file_observable(props, md5="d41d8cd98f00b204e9800998ecf8427e")
        self.assertEqual(observable["type"], "file")
        self.assertEqual(observable["name"], "malware.exe")
        self.assertEqual(observable["hashes"]["MD5"], "d41d8cd98f00b204e9800998ecf8427e")

    def test_invalid_file_observable(self):
        props = ObservableProperties(value="malware.exe", creator_identity="test-creator", labels=["malicious"], marking_definitions=["TLP:RED"])
        with self.assertRaises(ValueError):
            create_file_observable(props, md5="invalid_md5")

if __name__ == "__main__":
    unittest.main()
