To create a Python program that interacts with a MongoDB database to manage employee attendance records, we will use the `pymongo` library. This program will include functions for inserting and fetching attendance records, as well as retrieving employee contact information. We'll ensure that each function handles potential errors and validates input parameters. Additionally, we'll include test cases to verify the correctness of each function.

Here's a structured implementation:

```python
from pymongo import MongoClient
from pymongo.errors import PyMongoError
from datetime import datetime

# Establish a connection to the MongoDB server
client = MongoClient('mongodb://localhost:27017/')
db = client['attendance_db']
attendance_collection = db['attendance']
emp_collection = db['emp']

def insert_attendance_record(emp_id, name, date, time):
    try:
        # Validate input
        if not isinstance(emp_id, int) or not isinstance(name, str):
            return "Invalid input types for emp_id or name."

        # Convert date and time to datetime objects
        date_obj = datetime.strptime(date, '%Y-%m-%d')
        time_obj = datetime.strptime(time, '%H:%M:%S').time()

        # Insert record
        attendance_collection.insert_one({
            'emp_id': emp_id,
            'name': name,
            'date': date_obj,
            'time': time_obj
        })
        return "Attendance record inserted successfully."
    except PyMongoError as e:
        return f"An error occurred: {e}"
    except ValueError as e:
        return f"Date or time format error: {e}"

def fetch_all_attendance_records():
    try:
        records = list(attendance_collection.find({}, {'_id': 0}))
        return records if records else "No attendance records found."
    except PyMongoError as e:
        return f"An error occurred: {e}"

def fetch_attendance_by_date(date):
    try:
        date_obj = datetime.strptime(date, '%Y-%m-%d')
        records = list(attendance_collection.find({'date': date_obj}, {'_id': 0}))
        return records if records else f"No records found for date: {date}"
    except PyMongoError as e:
        return f"An error occurred: {e}"
    except ValueError as e:
        return f"Date format error: {e}"

def fetch_attendance_by_emp_id(emp_id):
    try:
        if not isinstance(emp_id, int):
            return "Invalid emp_id type."

        records = list(attendance_collection.find({'emp_id': emp_id}, {'_id': 0}))
        return records if records else f"No records found for employee ID: {emp_id}"
    except PyMongoError as e:
        return f"An error occurred: {e}"

def fetch_attendance_by_emp_id_and_date(emp_id, date):
    try:
        if not isinstance(emp_id, int):
            return "Invalid emp_id type."

        date_obj = datetime.strptime(date, '%Y-%m-%d')
        records = list(attendance_collection.find({'emp_id': emp_id, 'date': date_obj}, {'_id': 0}))
        return records if records else f"No records found for employee ID: {emp_id} on date: {date}"
    except PyMongoError as e:
        return f"An error occurred: {e}"
    except ValueError as e:
        return f"Date format error: {e}"

def get_employee_contact(emp_id):
    try:
        if not isinstance(emp_id, int):
            return "Invalid emp_id type."

        employee = emp_collection.find_one({'emp_id': emp_id}, {'_id': 0, 'contact': 1})
        return employee['contact'] if employee else f"No contact found for employee ID: {emp_id}"
    except PyMongoError as e:
        return f"An error occurred: {e}"

# Test cases
def test_functions():
    print(insert_attendance_record(1, "John Doe", "2023-10-01", "09:00:00"))
    print(fetch_all_attendance_records())
    print(fetch_attendance_by_date("2023-10-01"))
    print(fetch_attendance_by_emp_id(1))
    print(fetch_attendance_by_emp_id_and_date(1, "2023-10-01"))
    print(get_employee_contact(1))

# Run test cases
test_functions()
```

