# Function to perform Breadth-First Search to check if the graph is fully connected
def BFS(adj_matrix):
    visited = [False] * 16
    for src in range(len(adj_matrix)):
        for idx in range(16):
            if not visited[idx] and adj_matrix[src][idx] == 1:
