Below is a Python program that implements a simple text encryption and decryption service using a Caesar cipher and binary encoding. The program includes functionalities for encrypting text with a specified shift and decrypting binary-encoded strings back to text. It also includes input validation and unit tests.

```python
def caesar_cipher_encrypt(text, shift):
    if not text.isalpha():
        raise ValueError("Input text must contain only alphabetic characters.")
    if len(text) > 4096:
        raise ValueError("Input text exceeds the maximum allowed length of 4096 characters.")

    encrypted_text = []
    for char in text:
        if char.isupper():
            encrypted_text.append(chr((ord(char) - 65 + shift) % 26 + 65))
        elif char.islower():
            encrypted_text.append(chr((ord(char) - 97 + shift) % 26 + 97))
    return ''.join(encrypted_text)

def binary_encode(text):
    return ' '.join(format(ord(char), '08b') for char in text)

def binary_decode(binary_string):
    try:
        binary_values = binary_string.split()
        decoded_text = ''.join(chr(int(bv, 2)) for bv in binary_values)
        return decoded_text
    except ValueError:
        raise ValueError("Invalid binary string provided for decoding.")

def encrypt_text(text, shift):
    encrypted_text = caesar_cipher_encrypt(text, shift)
    return binary_encode(encrypted_text)

def decrypt_binary(binary_string):
    return binary_decode(binary_string)

# Unit tests
def test_caesar_cipher_encrypt():
    assert caesar_cipher_encrypt("ABC", 1) == "BCD"
    assert caesar_cipher_encrypt("xyz", 2) == "zab"
    try:
        caesar_cipher_encrypt("123", 1)
    except ValueError as e:
        assert str(e) == "Input text must contain only alphabetic characters."

def test_binary_encode_decode():
    text = "Hello"
    binary = binary_encode(text)
    assert binary_decode(binary) == text

def test_encrypt_decrypt():
    text = "HelloWorld"
    shift = 3
    encrypted_binary = encrypt_text(text, shift)
    decrypted_text = decrypt_binary(encrypted_binary)
    assert decrypted_text == caesar_cipher_encrypt(text, shift)

if __name__ == "__main__":
    # Run unit tests
    test_caesar_cipher_encrypt()
    test_binary_encode_decode()
    test_encrypt_decrypt()

    # Example usage
    try:
        text_to_encrypt = "HelloWorld"
        shift_value = 3
        encrypted_binary = encrypt_text(text_to_encrypt, shift_value)
        print(f"Encrypted Binary: {encrypted_binary}")

        decrypted_text = decrypt_binary(encrypted_binary)
        print(f"Decrypted Text: {decrypted_text}")
    except ValueError as e:
        print(f"Error: {e}")
```

