JIRA_URL = "https://issues.apache.org/jira/rest/api/2/search"

def fetch_issues(fix_version):
    username = os.getenv('JIRA_USERNAME')
    password = os.getenv('JIRA_PASSWORD')

    if not username or not password:
        print("Error: JIRA_USERNAME and JIRA_PASSWORD environment variables must be set.")
        sys.exit(1)

    query = {
        'jql': f'project=ARROW AND fixVersion="{fix_version}" AND resolution in (Fixed, Done)',
        'fields': 'key,summary,issuetype',
        'maxResults': 1000
    }

    try:
        response = requests.get(JIRA_URL, params=query, auth=HTTPBasicAuth(username, password))
        response.raise_for_status()
    except requests.exceptions.HTTPError as err:
        if response.status_code == 401:
            print("Error: Authentication failed. Please check your JIRA credentials.")
        else:
            print(f"HTTP error occurred: {err}")
        sys.exit(1)
    except requests.exceptions.RequestException as err:
        print(f"Network error occurred: {err}")
        sys.exit(1)

    return response.json().get('issues', [])

def group_issues(issues, is_website):
    grouped = {}
    for issue in issues:
        issue_type = issue['fields']['issuetype']['name'] if is_website else issue['fields']['issuetype']['name']
        if issue_type not in grouped:
            grouped[issue_type] = []
        grouped[issue_type].append(issue)

    for issue_type in grouped:
        grouped[issue_type].sort(key=lambda x: x['key'])

    return grouped

def format_markdown(grouped_issues):
    output = []
    for issue_type, issues in grouped_issues.items():
        output.append(f"## {issue_type}")
        for issue in issues:
            output.append(f"- [{issue['key']}](https://issues.apache.org/jira/browse/{issue['key']}): {issue['fields']['summary']}")
    return "\n".join(output)

def format_website(grouped_issues):
    output = []
    for issue_type, issues in grouped_issues.items():
        output.append(f"<h2>{issue_type}</h2>")
        output.append("<ul>")
        for issue in issues:
            output.append(f"<li><a href='https://issues.apache.org/jira/browse/{issue['key']}'>{issue['key']}</a>: {issue['fields']['summary']}</li>")
        output.append("</ul>")
    return "\n".join(output)

def main():
    if len(sys.argv) < 2:
        print("Usage: make_changelog.py $FIX_VERSION [$IS_WEBSITE]")
        sys.exit(1)

    fix_version = sys.argv[1]
    is_website = len(sys.argv) > 2 and sys.argv[2] == '1'

    issues = fetch_issues(fix_version)
    grouped_issues = group_issues(issues, is_website)

    if is_website:
        changelog = format_website(grouped_issues)
    else:
        changelog = format_markdown(grouped_issues)

    print(changelog)

if __name__ == "__main__":
    main()
```

