        'prefix': {'nick': 'User123'},
        'params': [bot.nick, '.echo Hello, World!']
    })

    # Simulate receiving a private message with .echo command but no text
    echo_module.handle_msg_privmsg(conn, {
        'prefix': {'nick': 'User123'},
        'params': [bot.nick, '.echo']
    })
