```python
import datetime
from dateutil import parser as dateutil_parser

class CongressError(Exception):
    """Custom exception for Congress API errors."""
    def __init__(self, message, response=None, url=None):
        super().__init__(message)
        self.response = response
        self.url = url

class NotFound(CongressError):
    """Exception for not found errors in the Congress API."""
    pass

def check_chamber(chamber):
    """Validate if the chamber is 'house', 'senate', or 'both'."""
    if chamber not in ['house', 'senate', 'both']:
        raise TypeError(f"Invalid chamber: {chamber}. Must be 'house', 'senate', or 'both'.")

def get_congress(year):
    """Calculate the Congress number based on the given year."""
    if year < 1789:
        raise CongressError("Year must be 1789 or later.")
    return (year - 1789) // 2 + 1

def parse_date(date_str):
    """Parse a date string into a datetime object."""
    if isinstance(date_str, (datetime.datetime, datetime.date)):
        return date_str
    try:
        return dateutil_parser.parse(date_str)
    except ImportError:
        return datetime.datetime.strptime(date_str, '%Y-%m-%d')

def u(text):
    """Ensure the text is returned as a Unicode string with LF line endings."""
    if isinstance(text, bytes):
        text = text.decode('utf-8')
    return text.replace('\r\n', '\n')

def get_offset(page_number):
    """Calculate the offset for pagination in the API."""
    if page_number < 1:
        raise CongressError("Page number must be 1 or greater.")
    return (page_number - 1) * 20

# Calculate the current Congress number based on the current year
CURRENT_YEAR = datetime.datetime.now().year
CURRENT_CONGRESS = get_congress(CURRENT_YEAR)

# Test cases to verify the correctness of each function
if __name__ == "__main__":
    # Test CongressError and NotFound
    try:
        raise CongressError("General error", url="http://example.com")
    except CongressError as e:
        assert str(e) == "General error"
        assert e.url == "http://example.com"

    try:
        raise NotFound("Item not found")
    except NotFound as e:
        assert str(e) == "Item not found"

    # Test check_chamber
    try:
        check_chamber('house')
        check_chamber('senate')
        check_chamber('both')
    except TypeError:
        assert False, "check_chamber raised TypeError unexpectedly"

    try:
        check_chamber('invalid')
    except TypeError:
        pass

    # Test get_congress
    assert get_congress(1789) == 1
    assert get_congress(2023) == 118

    try:
        get_congress(1788)
    except CongressError:
        pass

    # Test parse_date
    assert parse_date("2023-10-01") == datetime.datetime(2023, 10, 1)
    assert parse_date(datetime.date(2023, 10, 1)) == datetime.date(2023, 10, 1)

    # Test u
    assert u("Hello\r\nWorld") == "Hello\nWorld"
    assert u(b"Hello\r\nWorld") == "Hello\nWorld"

    # Test get_offset
    assert get_offset(1) == 0
    assert get_offset(2) == 20

    try:
        get_offset(0)
    except CongressError:
        pass

    # Test CURRENT_CONGRESS
    assert CURRENT_CONGRESS == get_congress(CURRENT_YEAR)
```

