class UnsupportedKeyTypeException(Exception):
    """Exception raised for unsupported key types."""
    pass

class FirstFollowSet:
    def __init__(self):
        self.sets = {}  # Dictionary to hold first and follow sets
        self.dirty = False  # Flag to track modifications

    def _normalize_key(self, key):
        """Normalize the key to a tuple of GrammarToken objects."""
        if isinstance(key, GrammarToken):
            return (key,)
        elif isinstance(key, list):
            return tuple(key)
        elif isinstance(key, tuple):
            return key
        else:
            raise UnsupportedKeyTypeException("Unsupported key type.")

    def _normalize_value(self, value):
        """Normalize the value to a set of GrammarToken objects."""
        if isinstance(value, GrammarToken):
            return {value}
        elif isinstance(value, list):
            return set(value)
        elif isinstance(value, set):
            return value
        else:
            raise UnsupportedKeyTypeException("Unsupported value type.")

    def add_empty(self, key):
        """Create an empty set for the given key if not present."""
        normalized_key = self._normalize_key(key)
        if normalized_key not in self.sets:
            self.sets[normalized_key] = set()
            self.dirty = True

    def add(self, key, value):
        """Add tokens to the set associated with the given key."""
        normalized_key = self._normalize_key(key)
        normalized_value = self._normalize_value(value)
        if normalized_key not in self.sets:
            self.sets[normalized_key] = set()
        initial_size = len(self.sets[normalized_key])
        self.sets[normalized_key].update(normalized_value)
        if len(self.sets[normalized_key]) > initial_size:
            self.dirty = True

    def remove(self, key, value):
        """Remove tokens from the set associated with the given key."""
        normalized_key = self._normalize_key(key)
        normalized_value = self._normalize_value(value)
        if normalized_key in self.sets:
            initial_size = len(self.sets[normalized_key])
            self.sets[normalized_key].difference_update(normalized_value)
            if len(self.sets[normalized_key]) < initial_size:
                self.dirty = True

    def get(self, key):
        """Retrieve the set associated with the given key."""
        normalized_key = self._normalize_key(key)
        return self.sets.get(normalized_key, set())

    def __str__(self):
        """Provide a string representation of the first and follow sets."""
        result = []
        for key, value in self.sets.items():
            key_str = ', '.join(str(token) for token in key)
            value_str = ', '.join(str(token) for token in value)
            result.append(f"{key_str}: {{{value_str}}}")
        return "\n".join(result)

    def reset_dirty_flag(self):
        """Reset the dirty flag."""
        self.dirty = False

