```python
import time

# Mock system module
class MockSystem:
    DEVICE_INFOS_TIMEOUT_MILLISEC = 5000  # Default timeout in milliseconds

    def __init__(self):
        self.device_infos = []

    def create_device(self, device_info):
        # Simulate the creation of a device object
        device = {'serial': device_info['serial'].lower(), 'info': device_info}
        self.device_infos.append(device)
        return device, "Device created successfully"

# Initialize the mock system
system = MockSystem()

class DeviceDiscoveryManager:
    def __init__(self):
        self.connected_devices = []

    def update_connected_devices(self):
        # Update the list of connected devices from the mock system
        self.connected_devices = system.device_infos

    def find_device_by_serial(self, serial):
        self.update_connected_devices()
        serial = serial.lower()
        for device in self.connected_devices:
            if device['serial'] == serial:
                return device['info']
        raise ValueError(f"Device with serial '{serial}' not found.")

    def wait_for_device_with_serial(self, serial, timeout):
        if timeout <= 0:
            raise ValueError("Timeout must be greater than zero.")

        serial = serial.lower()
        end_time = time.time() + timeout

        while time.time() < end_time:
            self.update_connected_devices()
            for device in self.connected_devices:
                if device['serial'] == serial:
                    return device['info']
            time.sleep(0.1)  # Sleep briefly to simulate waiting

        raise TimeoutError(f"Device with serial '{serial}' not found within {timeout} seconds.")

# Example usage
if __name__ == "__main__":
    # Simulate adding a device to the system
    system.create_device({'serial': 'ABC123', 'name': 'Device1'})

    manager = DeviceDiscoveryManager()

    try:
        device_info = manager.find_device_by_serial('abc123')
        print("Device found:", device_info)
    except ValueError as e:
        print(e)

    try:
        device_info = manager.wait_for_device_with_serial('abc123', 5)
        print("Device found:", device_info)
    except (ValueError, TimeoutError) as e:
        print(e)
```

