```python
class Test:
    def name(self):
        return self.__class__.__name__

    @classmethod
    def description(cls):
        return None


class TestRegistry:
    def __init__(self):
        self._registry = {}

    def register(self, test_class):
        if not issubclass(test_class, Test):
            raise ValueError("Class must inherit from Test")

        class_name = test_class.__name__
        if class_name in self._registry:
            raise ValueError(f"Class '{class_name}' is already registered")

        self._registry[class_name] = test_class

    def get(self, class_name):
        return self._registry.get(class_name, None)

    def list_registered(self):
        return list(self._registry.keys())


# Test cases
def test_registry():
    registry = TestRegistry()

    class SampleTest(Test):
        @classmethod
        def description(cls):
            return "This is a sample test class."

    class AnotherTest(Test):
        pass

    # Register SampleTest
    registry.register(SampleTest)
    assert registry.get("SampleTest") == SampleTest
    assert registry.list_registered() == ["SampleTest"]

    # Register AnotherTest
    registry.register(AnotherTest)
    assert registry.get("AnotherTest") == AnotherTest
    assert set(registry.list_registered()) == {"SampleTest", "AnotherTest"}

    # Attempt to register SampleTest again should raise ValueError
    try:
        registry.register(SampleTest)
    except ValueError as e:
        assert str(e) == "Class 'SampleTest' is already registered"

    # Attempt to register a class not inheriting from Test should raise ValueError
    class NotATest:
        pass

    try:
        registry.register(NotATest)
    except ValueError as e:
        assert str(e) == "Class must inherit from Test"

    # Check descriptions
    assert SampleTest.description() == "This is a sample test class."
    assert AnotherTest.description() is None

