Here's a Python class `MockTestRunner` that simulates the execution of layout tests for a web rendering engine. This class handles different types of tests, including text comparison tests, pixel tests, audio tests, virtual tests, and reference tests. It provides methods to add tests, run them, and return a structured summary of the results.

```python
class MockTestRunner:
    def __init__(self):
        self.tests = []
        self.results = {
            'passed': [],
            'failed': [],
            'skipped': []
        }

    def add_test(self, test_name, test_type, expected_result, actual_result=None):
        if test_type not in ['text', 'pixel', 'audio', 'virtual', 'reftest']:
            raise ValueError(f"Invalid test type: {test_type}")

        if expected_result is None:
            raise ValueError("Expected result must be provided")

        self.tests.append({
            'name': test_name,
            'type': test_type,
            'expected': expected_result,
            'actual': actual_result,
            'status': 'pending'
        })

    def run_tests(self):
        for test in self.tests:
            if test['actual'] is None:
                test['status'] = 'skipped'
                self.results['skipped'].append(test)
                continue

            if test['expected'] == test['actual']:
                test['status'] = 'passed'
                self.results['passed'].append(test)
            else:
                test['status'] = 'failed'
                self.results['failed'].append(test)

        return self.get_summary()

    def get_summary(self):
        return {
            'total': len(self.tests),
            'passed': len(self.results['passed']),
            'failed': len(self.results['failed']),
            'skipped': len(self.results['skipped']),
            'details': self.results
        }

    def get_detailed_results(self):
        detailed_results = []
        for test in self.tests:
            detailed_results.append({
                'name': test['name'],
                'type': test['type'],
                'expected': test['expected'],
                'actual': test['actual'],
                'status': test['status']
            })
        return detailed_results

    def filter_results_by_status(self, status):
        if status not in self.results:
            raise ValueError(f"Invalid status: {status}")
        return self.results[status]

# Example usage:
runner = MockTestRunner()
runner.add_test('test1', 'text', 'expected text', 'expected text')
runner.add_test('test2', 'pixel', 'checksum123', 'checksum456')
runner.add_test('test3', 'audio', 'audio123', None)  # This will be skipped
runner.add_test('test4', 'reftest', 'ref123', 'ref123')

summary = runner.run_tests()
print(summary)

detailed_results = runner.get_detailed_results()
for result in detailed_results:
    print(result)

# Filtering results
passed_tests = runner.filter_results_by_status('passed')
print("Passed Tests:", passed_tests)
```

### Key Features:
- **Add Tests**: The `add_test` method allows adding tests with their expected and actual results. It checks for valid test types and ensures expected results are provided.
