        self.call_start_times = {}
        self.lock = threading.Lock()

    def start_call(self, call_id: int, endpoints: List[Endpoint], encryption_key: bytes, is_outgoing: bool):
        if not isinstance(call_id, int):
            raise ValueError("call_id must be an integer")
        if not isinstance(endpoints, list) or not all(isinstance(e, Endpoint) for e in endpoints):
            raise ValueError("endpoints must be a list of Endpoint objects")
        if not isinstance(encryption_key, bytes):
            raise ValueError("encryption_key must be bytes")
        if not isinstance(is_outgoing, bool):
            raise ValueError("is_outgoing must be a boolean")

        with self.lock:
            if call_id in self.calls:
                raise ValueError(f"Call with ID {call_id} already exists")

            controller = VoIPController(endpoints, encryption_key, is_outgoing)
            self.calls[call_id] = controller
            self.call_start_times[call_id] = datetime.now()
            controller.start()

    def end_call(self, call_id: int):
        with self.lock:
            if call_id not in self.calls:
                raise ValueError(f"No call with ID {call_id} found")

            controller = self.calls.pop(call_id)
            controller.stop()
            self.call_start_times.pop(call_id, None)

    def get_call_duration(self, call_id: int) -> float:
        with self.lock:
            if call_id not in self.call_start_times:
                raise ValueError(f"No call with ID {call_id} found")

            start_time = self.call_start_times[call_id]
            return (datetime.now() - start_time).total_seconds()

