To create a `MysqlManager` class that meets the specified requirements, we'll use the `mysql-connector-python` library to interact with the MySQL database. This library provides a Python interface for connecting to MySQL databases and executing SQL commands. Below is the implementation of the `MysqlManager` class:

```python
import mysql.connector
from mysql.connector import errorcode

class MysqlManager:
    def __init__(self, host, user, password):
        """Initialize the MysqlManager with database credentials and establish a connection."""
        self.host = host
        self.user = user
        self.password = password
        self.connection = None
        self.cursor = None
        try:
            self.connection = mysql.connector.connect(
                host=self.host,
                user=self.user,
                password=self.password
            )
            self.cursor = self.connection.cursor()
            print("Connection to MySQL server established successfully.")
        except mysql.connector.Error as err:
            self.handle_error(err)

    def create_database(self, db_name):
        """Create a new database if it does not exist."""
        try:
            self.cursor.execute(f"CREATE DATABASE IF NOT EXISTS {db_name}")
            print(f"Database '{db_name}' created or already exists.")
        except mysql.connector.Error as err:
            self.handle_error(err)

    def create_table(self, db_name, table_name, table_schema):
        """Create a new table in the specified database."""
        try:
            self.cursor.execute(f"USE {db_name}")
            self.cursor.execute(f"CREATE TABLE IF NOT EXISTS {table_name} ({table_schema})")
            print(f"Table '{table_name}' created or already exists in database '{db_name}'.")
        except mysql.connector.Error as err:
            self.handle_error(err)

    def insert(self, insert_command):
        """Insert a record into a table using a validated SQL command."""
        try:
            # Validate the SQL command to prevent SQL injection
            if not self.validate_sql(insert_command):
                raise ValueError("Invalid SQL command detected.")
            self.cursor.execute(insert_command)
            print("Record inserted successfully.")
        except (mysql.connector.Error, ValueError) as err:
            self.handle_error(err)

    def commit(self):
        """Commit the current transaction."""
        try:
            self.connection.commit()
            print("Transaction committed successfully.")
        except mysql.connector.Error as err:
            self.handle_error(err)

    def validate_sql(self, sql_command):
        """Validate the SQL command to prevent SQL injection."""
        # Basic validation: ensure the command is an INSERT statement
        return sql_command.strip().upper().startswith("INSERT")

    def handle_error(self, err):
        """Handle errors and print user-friendly messages."""
        if isinstance(err, mysql.connector.Error):
            if err.errno == errorcode.ER_ACCESS_DENIED_ERROR:
                print("Error: Access denied. Please check your username and password.")
            elif err.errno == errorcode.ER_BAD_DB_ERROR:
                print("Error: Database does not exist.")
            else:
                print(f"Error: {err.msg}")
        else:
            print(f"Error: {err}")

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Ensure the database connection and cursor are closed."""
        if self.cursor:
            self.cursor.close()
        if self.connection:
            self.connection.close()
        print("Database connection closed.")

    def __del__(self):
        """Destructor to ensure resources are cleaned up."""
        self.__exit__(None, None, None)

# Example usage:
# manager = MysqlManager('localhost', 'root', 'password')
# manager.create_database('test_db')
