```python
from flask import Flask, request, jsonify
from scipy import stats
import numpy as np

app = Flask(__name__)

def validate_samples(samples, min_length=1):
    if not isinstance(samples, list) or len(samples) < min_length:
        return False, "Samples must be a list with at least {} elements.".format(min_length)
    if not all(isinstance(x, (int, float)) for x in samples):
        return False, "All elements in samples must be numbers."
    return True, ""

@app.route('/ztest', methods=['POST'])
def ztest():
    data = request.get_json()
    samples1 = data.get('samples1')
    samples2 = data.get('samples2', None)

    valid, message = validate_samples(samples1, 30)
    if not valid:
        return jsonify({'error': message}), 400

    if samples2:
        valid, message = validate_samples(samples2, 30)
        if not valid:
            return jsonify({'error': message}), 400
        # Two-sample Z-test
        z_stat, p_value = stats.ttest_ind(samples1, samples2, equal_var=True)
    else:
        # One-sample Z-test
        population_mean = data.get('population_mean', 0)
        z_stat, p_value = stats.ttest_1samp(samples1, population_mean)

    return jsonify({'z_stat': z_stat, 'p_value': p_value})

@app.route('/ttest-equalvariance', methods=['POST'])
def ttest_equalvariance():
    data = request.get_json()
    samples1 = data.get('samples1')
    samples2 = data.get('samples2')

    valid, message = validate_samples(samples1, 2)
    if not valid:
        return jsonify({'error': message}), 400

    valid, message = validate_samples(samples2, 2)
    if not valid:
        return jsonify({'error': message}), 400

    t_stat, p_value = stats.ttest_ind(samples1, samples2, equal_var=True)
    return jsonify({'t_stat': t_stat, 'p_value': p_value})

@app.route('/ttest-unequalvariance', methods=['POST'])
def ttest_unequalvariance():
    data = request.get_json()
    samples1 = data.get('samples1')
    samples2 = data.get('samples2')

    valid, message = validate_samples(samples1, 2)
    if not valid:
        return jsonify({'error': message}), 400

    valid, message = validate_samples(samples2, 2)
    if not valid:
        return jsonify({'error': message}), 400

    t_stat, p_value = stats.ttest_ind(samples1, samples2, equal_var=False)
    return jsonify({'t_stat': t_stat, 'p_value': p_value})

@app.route('/normaltest', methods=['POST'])
def normaltest():
    data = request.get_json()
    samples = data.get('samples')

    valid, message = validate_samples(samples, 2)
    if not valid:
        return jsonify({'error': message}), 400

    k2, p_value = stats.normaltest(samples)
