To achieve the task of processing a JSON Lines file containing documentation data for various C++ code elements, we can create a Python script that reads the input file, extracts the necessary information, and writes the output to separate JSON files. Additionally, we'll include unit tests to ensure the correctness of the data extraction. Below is the complete implementation of the script along with the unit tests.

```python
import json
import os
import sys
from typing import List, Dict, Any

def process_json_lines(source: str, target_directory: str):
    # Ensure the target directory exists
    os.makedirs(target_directory, exist_ok=True)

    # Initialize containers for each type of element
    functions = []
    defines = []
    typedefs = []
    enumerations = []
    enum_members = []

    try:
        with open(source, 'r') as file:
            for line in file:
                try:
                    data = json.loads(line)
                    kind = data.get('kind')
                    if kind == 'function':
                        functions.append(extract_function_data(data))
                    elif kind == 'define':
                        defines.append(extract_define_data(data))
                    elif kind == 'typedef':
                        typedefs.append(extract_typedef_data(data))
                    elif kind == 'enumeration':
                        enumerations.append(extract_enumeration_data(data))
                    elif kind == 'enum_member':
                        enum_members.append(extract_enum_member_data(data))
                except json.JSONDecodeError:
                    print(f"Error decoding JSON line: {line.strip()}")
                    continue

        # Write the extracted data to JSON files
        write_json_file(os.path.join(target_directory, 'functions.json'), functions)
        write_json_file(os.path.join(target_directory, 'defines.json'), defines)
        write_json_file(os.path.join(target_directory, 'typedefs.json'), typedefs)
        write_json_file(os.path.join(target_directory, 'enumerations.json'), enumerations)
        write_json_file(os.path.join(target_directory, 'enum_members.json'), enum_members)

    except FileNotFoundError:
        print(f"Error: The file {source} was not found.")
    except Exception as e:
        print(f"An error occurred: {e}")

def extract_function_data(data: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'name': data.get('name'),
        'signature': data.get('signature'),
        'documentation': data.get('documentation'),
        'parameters': data.get('parameters', []),
        'template_arguments': data.get('template_arguments', [])
    }

def extract_define_data(data: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'name': data.get('name'),
        'value': data.get('value'),
        'documentation': data.get('documentation')
    }

def extract_typedef_data(data: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'name': data.get('name'),
        'value': data.get('value'),
        'documentation': data.get('documentation')
    }

def extract_enumeration_data(data: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'name': data.get('name'),
        'documentation': data.get('documentation')
    }

def extract_enum_member_data(data: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'name': data.get('name'),
        'value': data.get('value'),
        'documentation': data.get('documentation')
    }

def write_json_file(filepath: str, data: List[Dict[str, Any]]):
    with open(filepath, 'w') as file:
        json.dump(data, file, indent=4)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python script.py <source> <target-directory>")
    else:
        source = sys.argv[1]
        target_directory = sys.argv[2]
        process_json_lines(source, target_directory)

# Unit tests
import unittest
from unittest.mock import mock_open, patch

class TestJsonLinesProcessing(unittest.TestCase):

    def test_extract_function_data(self):
        data = {
            'kind': 'function',
            'name': 'foo',
            'signature': 'void foo(int a)',
            'documentation': 'This is a function.',
            'parameters': ['int a'],
            'template_arguments': ['typename T']
        }
        expected = {
            'name': 'foo',
            'signature': 'void foo(int a)',
            'documentation': 'This is a function.',
            'parameters': ['int a'],
            'template_arguments': ['typename T']
        }
        self.assertEqual(extract_function_data(data), expected)

    def test_extract_define_data(self):
        data = {
            'kind': 'define',
            'name': 'MAX_SIZE',
            'value': '100',
            'documentation': 'Maximum size.'
        }
        expected = {
            'name': 'MAX_SIZE',
            'value': '100',
            'documentation': 'Maximum size.'
        }
        self.assertEqual(extract_define_data(data), expected)

    def test_extract_typedef_data(self):
        data = {
            'kind': 'typedef',
            'name': 'IntPtr',
            'value': 'int*',
            'documentation': 'Pointer to an integer.'
        }
        expected = {
            'name': 'IntPtr',
            'value': 'int*',
