        </label>
        <button type="submit">Submit Vote</button>
    </form>
    <div id="voteTotals">
        <h2>Current Vote Totals</h2>
        <p>Yes: <span id="yesCount">0</span></p>
        <p>No: <span id="noCount">0</span></p>
        <p>Maybe: <span id="maybeCount">0</span></p>
    </div>
    <div id="feedback"></div>
</body>
</html>
```

### static/main.js

This JavaScript file handles form submission and real-time updates.

```javascript
document.addEventListener('DOMContentLoaded', () => {
    const socket = io();

    const form = document.getElementById('voteForm');
    const feedback = document.getElementById('feedback');
    const yesCount = document.getElementById('yesCount');
    const noCount = document.getElementById('noCount');
    const maybeCount = document.getElementById('maybeCount');

    form.addEventListener('submit', (event) => {
        event.preventDefault();
        const formData = new FormData(form);
        const vote = formData.get('vote');

        if (vote) {
            socket.emit('submit_vote', { option: vote });
            feedback.textContent = 'Vote submitted successfully!';
        } else {
            feedback.textContent = 'Please select an option before submitting.';
        }
    });

    socket.on('vote_totals', (totals) => {
        yesCount.textContent = totals.yes;
        noCount.textContent = totals.no;
        maybeCount.textContent = totals.maybe;
    });

    socket.on('error', (data) => {
        feedback.textContent = data.message;
    });
});
```

