from socketio_events import vote_totals, handle_vote

class TestVoteLogic(unittest.TestCase):
    def setUp(self):
        # Reset vote totals before each test
        vote_totals['yes'] = 0
        vote_totals['no'] = 0
        vote_totals['maybe'] = 0

    def test_valid_vote(self):
        handle_vote({'option': 'yes'})
        self.assertEqual(vote_totals['yes'], 1)

    def test_invalid_vote(self):
        handle_vote({'option': 'invalid'})
        self.assertEqual(vote_totals['yes'], 0)
        self.assertEqual(vote_totals['no'], 0)
        self.assertEqual(vote_totals['maybe'], 0)

if __name__ == '__main__':
    unittest.main()
```

