```python
class Date:
    def __init__(self, day, month, year):
        self.set_year(year)
        self.set_month(month)
        self.set_day(day)

    def __str__(self):
        return f"{self.day:02d}-{self.month:02d}-{self.year}"

    def set_day(self, day):
        if not (1 <= day <= 31):
            raise ValueError("Day must be between 1 and 31.")
        if day > self.days_in_month(self.month, self.year):
            raise ValueError(f"Invalid day for the month: {self.month}.")
        self.day = day

    def set_month(self, month):
        if not (1 <= month <= 12):
            raise ValueError("Month must be between 1 and 12.")
        self.month = month

    def set_year(self, year):
        if year <= 0:
            raise ValueError("Year must be a positive integer.")
        self.year = year

    def add_days(self, days):
        if days < 0:
            raise ValueError("Days to add must be a non-negative integer.")
        while days > 0:
            days_in_current_month = self.days_in_month(self.month, self.year)
            if self.day + days <= days_in_current_month:
                self.day += days
                break
            else:
                days -= (days_in_current_month - self.day + 1)
                self.day = 1
                if self.month == 12:
                    self.month = 1
                    self.year += 1
                else:
                    self.month += 1

    @staticmethod
    def days_in_month(month, year):
        if month in {1, 3, 5, 7, 8, 10, 12}:
            return 31
        elif month in {4, 6, 9, 11}:
            return 30
        elif month == 2:
            return 29 if Date.is_leap_year(year) else 28
        else:
            raise ValueError("Invalid month.")

    @staticmethod
    def is_leap_year(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

# Example usage:
try:
    date = Date(28, 2, 2020)
    print(date)  # Output: 28-02-2020
    date.add_days(1)
    print(date)  # Output: 29-02-2020
    date.add_days(1)
    print(date)  # Output: 01-03-2020
except ValueError as e:
    print(e)
```

