class Audit:
    def __init__(self, audit_id):
        self.audit_id = audit_id
        self.archived = False
        self.assessments = []
        self.evidence = []

    def add_assessment(self, assessment):
        self.assessments.append(assessment)

    def add_evidence(self, evidence):
        self.evidence.append(evidence)


class Assessment:
    def __init__(self, assessment_id):
        self.assessment_id = assessment_id
        self.archived = False


class Evidence:
    def __init__(self, evidence_id):
        self.evidence_id = evidence_id
        self.archived = False


class ArchiveSystem:
    def __init__(self):
        self.audits = {}

    def add_audit(self, audit):
        self.audits[audit.audit_id] = audit

    def archive_audit(self, audit_id):
        if audit_id not in self.audits:
            return f"Error: Audit with ID {audit_id} does not exist."

        audit = self.audits[audit_id]

        # Attempt to archive all related assessments and evidence
        try:
            for assessment in audit.assessments:
                assessment.archived = True
            for evidence in audit.evidence:
                evidence.archived = True
            audit.archived = True
            return f"Audit {audit_id} and all related items archived successfully."
        except Exception as e:
            # Rollback in case of any failure
            for assessment in audit.assessments:
                assessment.archived = False
            for evidence in audit.evidence:
                evidence.archived = False
            audit.archived = False
            return f"Error: Failed to archive audit {audit_id}. Reason: {str(e)}"

    def query_archived_items(self, item_type):
        if item_type not in ['Audit', 'Assessment', 'Evidence']:
            return "Error: Invalid item type. Please specify 'Audit', 'Assessment', or 'Evidence'."

        archived_ids = []
        if item_type == 'Audit':
            archived_ids = [audit_id for audit_id, audit in self.audits.items() if audit.archived]
        elif item_type == 'Assessment':
            for audit in self.audits.values():
                archived_ids.extend([assessment.assessment_id for assessment in audit.assessments if assessment.archived])
        elif item_type == 'Evidence':
            for audit in self.audits.values():
                archived_ids.extend([evidence.evidence_id for evidence in audit.evidence if evidence.archived])

        return archived_ids


