```python
import click

def style_title(text, underline_char='-', title_case=False):
    """Styles the text as a title with an underline."""
    if title_case:
        text = text.title()
    underline = underline_char * len(text)
    return f"{text}\n{underline}"

def style_box(text, border_char='*'):
    """Styles the text inside a box made of the specified border character."""
    lines = text.split('\n')
    max_length = max(len(line) for line in lines)
    border = border_char * (max_length + 4)
    boxed_text = [border]
    for line in lines:
        boxed_text.append(f"{border_char} {line.ljust(max_length)} {border_char}")
    boxed_text.append(border)
    return "\n".join(boxed_text)

def simulate_evaluation(verbose=False):
    """Simulates an evaluation process and returns a detailed or summary output."""
    results = {
        'command1': 'success',
        'command2': 'failure',
        'command3': 'success'
    }
    if verbose:
        return "\n".join(f"{cmd}: {status}" for cmd, status in results.items())
    else:
        failed = [cmd for cmd, status in results.items() if status == 'failure']
        return "Evaluation Summary: " + ("All commands succeeded." if not failed else f"Failed commands: {', '.join(failed)}")

def summarize_evaluation(evaluation):
    """Prints a summary of the evaluation."""
    failed = [line for line in evaluation.split('\n') if 'failure' in line]
    if not failed:
        return "Evaluation Summary: All commands succeeded."
    else:
        return f"Evaluation Summary: Failed commands: {', '.join(failed)}"

@click.group()
def cli():
    """A CLI tool for generating styled text outputs."""
    pass

@cli.command()
@click.argument('text')
@click.option('--underline-char', default='-', help='Character to use for underlining the title.')
@click.option('--title-case', is_flag=True, help='Transform text to title case.')
def title(text, underline_char, title_case):
    """Prints the text as a title with an underline."""
    styled_title = style_title(text, underline_char, title_case)
    click.echo(styled_title)

@cli.command()
@click.argument('text')
@click.option('--border-char', default='*', help='Character to use for the box border.')
def box(text, border_char):
    """Prints the text inside a box."""
    boxed_text = style_box(text, border_char)
    click.echo(boxed_text)

@cli.command()
@click.option('--verbose', is_flag=True, help='Show detailed evaluation results.')
def evaluation(verbose):
    """Simulates an evaluation process and prints the results."""
    eval_output = simulate_evaluation(verbose)
    click.echo(eval_output)

@cli.command()
@click.argument('evaluation')
def summary(evaluation):
    """Prints a summary of the evaluation."""
    summary_output = summarize_evaluation(evaluation)
    click.echo(summary_output)

if __name__ == '__main__':
    cli()
```

### Explanation:

1. **Title Command**: The `title` command takes a string and prints it as a title with an underline. It has options for specifying the underline character and whether to transform the text to title case.

2. **Box Command**: The `box` command takes a string and prints it inside a box made of a specified border character.

3. **Evaluation Command**: The `evaluation` command simulates an evaluation process and prints detailed results if verbosity is enabled, or a summary otherwise.

4. **Summary Command**: The `summary` command takes an evaluation string and prints a summary, indicating whether it was successful or which commands failed.

