import re
from datetime import datetime

class Album:
    def __init__(self, nombre, fechaPublicacion, generos, descripcion):
        self.nombre = nombre
        self.fechaPublicacion = fechaPublicacion
        self.generos = generos
        self.descripcion = descripcion
        self.albumsSimilares = []
        self.playsCanciones = {}

        # Validate the release date format
        if not self._validarFecha(fechaPublicacion):
            raise ValueError("La fecha de publicación debe estar en el formato 'YYYY-MM-DD'.")

        # Ensure genres is a list
        if not isinstance(generos, list):
            raise TypeError("Los géneros deben ser una lista de cadenas.")

    def _validarFecha(self, fecha):
        # Check if the date is in the correct format
        try:
            datetime.strptime(fecha, '%Y-%m-%d')
            return True
        except ValueError:
            return False

    def agregarGenero(self, genero):
        if not isinstance(genero, str):
            raise TypeError("El género debe ser una cadena.")
        if genero not in self.generos:
            self.generos.append(genero)

    def getAlbumsSimilares(self):
        return self.albumsSimilares

    def setAlbumsSimilares(self, albums):
        if not all(isinstance(album, Album) for album in albums):
            raise TypeError("Todos los elementos deben ser instancias de Album.")
        self.albumsSimilares = albums

    def getPlaysCanciones(self):
        return self.playsCanciones

    def setPlaysCanciones(self, plays):
        if not isinstance(plays, dict):
            raise TypeError("Las reproducciones deben ser un diccionario.")
        for song, count in plays.items():
            if not isinstance(song, str):
                raise TypeError("El nombre de la canción debe ser una cadena.")
            if not isinstance(count, int) or count < 0:
                raise ValueError("El número de reproducciones debe ser un entero no negativo.")
        self.playsCanciones = plays

# Example usage:
try:
