import random
import unittest

class EnvironmentSensor:
    def read_temperature(self):
        """Simulate reading the temperature in degrees Celsius."""
        return random.uniform(-40, 50)

    def read_humidity(self):
        """Simulate reading the humidity as a percentage."""
        return random.uniform(0, 100)

    def read_pressure(self):
        """Simulate reading the pressure in hPa."""
        return random.uniform(300, 1100)

    def read_accelerometer(self):
        """Simulate reading the accelerometer values for x, y, z axes."""
        return (random.uniform(-2, 2), random.uniform(-2, 2), random.uniform(-2, 2))

    def read_gyroscope(self):
        """Simulate reading the gyroscope values for x, y, z axes."""
        return (random.uniform(-250, 250), random.uniform(-250, 250), random.uniform(-250, 250))

    def read_compass(self):
        """Simulate reading the compass values for x, y, z axes."""
        return (random.uniform(-1, 1), random.uniform(-1, 1), random.uniform(-1, 1))


# Test suite for the EnvironmentSensor class
class TestEnvironmentSensor(unittest.TestCase):
    def setUp(self):
        self.sensor = EnvironmentSensor()

    def test_temperature_range(self):
        temp = self.sensor.read_temperature()
        self.assertGreaterEqual(temp, -40)
        self.assertLessEqual(temp, 50)

    def test_humidity_range(self):
        humidity = self.sensor.read_humidity()
        self.assertGreaterEqual(humidity, 0)
        self.assertLessEqual(humidity, 100)

    def test_pressure_range(self):
        pressure = self.sensor.read_pressure()
        self.assertGreaterEqual(pressure, 300)
        self.assertLessEqual(pressure, 1100)

    def test_accelerometer_range(self):
        x, y, z = self.sensor.read_accelerometer()
        for value in (x, y, z):
            self.assertGreaterEqual(value, -2)
            self.assertLessEqual(value, 2)

    def test_gyroscope_range(self):
        x, y, z = self.sensor.read_gyroscope()
        for value in (x, y, z):
            self.assertGreaterEqual(value, -250)
            self.assertLessEqual(value, 250)

    def test_compass_range(self):
        x, y, z = self.sensor.read_compass()
        for value in (x, y, z):
            self.assertGreaterEqual(value, -1)
            self.assertLessEqual(value, 1)


# Run the tests
if __name__ == '__main__':
    unittest.main()
```

