To create a smart home system that simulates switches acting as covers, we'll use a class-based approach in Python. We'll define classes for the SmartHomeSystem, Switch, and Cover, and implement methods to manage their states. We'll also include a simple testing framework using Python's `unittest` module to verify the functionality.

Here's the implementation:

```python
import unittest
import logging

# Set up logging
logging.basicConfig(level=logging.DEBUG)

# Constants for device states
ON = "ON"
OFF = "OFF"
UNAVAILABLE = "UNAVAILABLE"

class Device:
    def __init__(self, name):
        self.name = name
        self.state = OFF

    def set_state(self, state):
        if self.state != UNAVAILABLE:
            self.state = state
            logging.debug(f"{self.name} state set to {self.state}")
        else:
            logging.warning(f"Cannot change state of {self.name} as it is UNAVAILABLE")

    def toggle_state(self):
        if self.state == ON:
            self.set_state(OFF)
        elif self.state == OFF:
            self.set_state(ON)

    def get_state(self):
        return self.state

class Switch(Device):
    def __init__(self, name):
        super().__init__(name)

class Cover(Device):
    def __init__(self, name):
        super().__init__(name)

    def open_cover(self):
        self.set_state(ON)

    def close_cover(self):
        self.set_state(OFF)

class SmartHomeSystem:
    def __init__(self):
        self.devices = {}

    def add_switch_as_cover(self, switch_name, cover_name):
        switch = Switch(switch_name)
        cover = Cover(cover_name)
        self.devices[switch_name] = switch
        self.devices[cover_name] = cover

    def toggle_switch(self, switch_name):
        if switch_name in self.devices:
            self.devices[switch_name].toggle_state()
            self.sync_cover_with_switch(switch_name)

    def turn_on_switch(self, switch_name):
        if switch_name in self.devices:
            self.devices[switch_name].set_state(ON)
            self.sync_cover_with_switch(switch_name)

    def turn_off_switch(self, switch_name):
        if switch_name in self.devices:
            self.devices[switch_name].set_state(OFF)
            self.sync_cover_with_switch(switch_name)

    def open_cover(self, cover_name):
        if cover_name in self.devices:
            self.devices[cover_name].open_cover()

    def close_cover(self, cover_name):
        if cover_name in self.devices:
            self.devices[cover_name].close_cover()

    def sync_cover_with_switch(self, switch_name):
        cover_name = switch_name.replace("Switch", "Cover")
        if cover_name in self.devices:
            switch_state = self.devices[switch_name].get_state()
            self.devices[cover_name].set_state(switch_state)

    def get_device_state(self, device_name):
        if device_name in self.devices:
            return self.devices[device_name].get_state()
        return None

# Unit tests
class TestSmartHomeSystem(unittest.TestCase):
    def setUp(self):
        self.system = SmartHomeSystem()
        self.system.add_switch_as_cover("LivingRoomSwitch", "LivingRoomCover")

    def test_initial_state(self):
        self.assertEqual(self.system.get_device_state("LivingRoomSwitch"), OFF)
        self.assertEqual(self.system.get_device_state("LivingRoomCover"), OFF)

    def test_toggle_switch(self):
        self.system.toggle_switch("LivingRoomSwitch")
        self.assertEqual(self.system.get_device_state("LivingRoomSwitch"), ON)
        self.assertEqual(self.system.get_device_state("LivingRoomCover"), ON)

    def test_turn_on_switch(self):
        self.system.turn_on_switch("LivingRoomSwitch")
        self.assertEqual(self.system.get_device_state("LivingRoomSwitch"), ON)
        self.assertEqual(self.system.get_device_state("LivingRoomCover"), ON)

    def test_turn_off_switch(self):
        self.system.turn_on_switch("LivingRoomSwitch")
        self.system.turn_off_switch("LivingRoomSwitch")
        self.assertEqual(self.system.get_device_state("LivingRoomSwitch"), OFF)
        self.assertEqual(self.system.get_device_state("LivingRoomCover"), OFF)

    def test_open_cover(self):
        self.system.open_cover("LivingRoomCover")
        self.assertEqual(self.system.get_device_state("LivingRoomCover"), ON)

    def test_close_cover(self):
        self.system.open_cover("LivingRoomCover")
        self.system.close_cover("LivingRoomCover")
        self.assertEqual(self.system.get_device_state("LivingRoomCover"), OFF)

    def test_unavailable_device(self):
        self.system.devices["LivingRoomSwitch"].set_state(UNAVAILABLE)
        self.system.toggle_switch("LivingRoomSwitch")
        self.assertEqual(self.system.get_device_state("LivingRoomSwitch"), UNAVAILABLE)
        self.assertEqual(self.system.get_device_state("LivingRoomCover"), OFF)

if __name__ == "__main__":
    unittest.main()
```

### Explanation:

1. **Device Class**: A base class for all devices, managing the state and providing methods to set and toggle the state.

2. **Switch and Cover Classes**: Inherit from `Device`. The `Cover` class has additional methods to open and close the cover.

3. **SmartHomeSystem Class**: Manages the devices, allowing adding switches as covers, toggling, turning on/off switches, and opening/closing covers. It ensures synchronization between switch and cover states.

4. **Unit Tests**: Using `unittest`, we test various scenarios to ensure the system behaves as expected, including handling unavailable devices.

5. **Logging**: Provides debug and warning messages to help trace the program's execution and handle errors gracefully.

This implementation ensures single responsibility for each method and provides a clear structure for managing smart home devices.

