```python
import sqlite3
import logging

# Configure logging
logging.basicConfig(level=logging.DEBUG)

class Persistence:
    def __init__(self, filepath):
        """Initializes a new database connection and creates the NotDelivered table if it doesn't exist."""
        try:
            self.connection = sqlite3.connect(filepath)
            self.cursor = self.connection.cursor()
            self.cursor.execute('''
                CREATE TABLE IF NOT EXISTS NotDelivered (
                    containerId TEXT PRIMARY KEY,
                    temperature INTEGER,
                    humidity INTEGER,
                    latitude REAL,
                    longitude REAL,
                    timestamp TEXT
                )
            ''')
            self.connection.commit()
            logging.info("Database initialized successfully.")
        except sqlite3.Error as e:
            logging.error(f"Error initializing database: {e}")
            raise

    def insert(self, data):
        """Inserts a new record into the NotDelivered table."""
        try:
            # Validate data structure
            if not isinstance(data, dict):
                raise ValueError("Data must be a dictionary.")

            required_keys = {'containerId', 'temperature', 'humidity', 'geo', 'timestamp'}
            if not required_keys.issubset(data.keys()):
                raise ValueError("Data dictionary is missing required keys.")

            if not isinstance(data['geo'], dict) or not {'latitude', 'longitude'}.issubset(data['geo'].keys()):
                raise ValueError("Geo must be a dictionary with 'latitude' and 'longitude' keys.")

            # Validate data types
            if not isinstance(data['containerId'], str):
                raise ValueError("containerId must be a string.")
            if not isinstance(data['temperature'], int):
                raise ValueError("temperature must be an integer.")
            if not isinstance(data['humidity'], int):
                raise ValueError("humidity must be an integer.")
            if not isinstance(data['geo']['latitude'], float):
                raise ValueError("latitude must be a float.")
            if not isinstance(data['geo']['longitude'], float):
                raise ValueError("longitude must be a float.")
            if not isinstance(data['timestamp'], str):
                raise ValueError("timestamp must be a string.")

            # Insert data into the database
            self.cursor.execute('''
                INSERT INTO NotDelivered (containerId, temperature, humidity, latitude, longitude, timestamp)
                VALUES (?, ?, ?, ?, ?, ?)
            ''', (data['containerId'], data['temperature'], data['humidity'], data['geo']['latitude'], data['geo']['longitude'], data['timestamp']))
            self.connection.commit()
            logging.info(f"Record inserted successfully: {data['containerId']}")
        except sqlite3.Error as e:
            logging.error(f"SQLite error: {e}")
            raise
        except ValueError as e:
            logging.error(f"Validation error: {e}")
            raise

    def close(self):
        """Closes the database connection."""
        try:
            if self.connection:
                self.connection.close()
                logging.info("Database connection closed.")
        except sqlite3.Error as e:
            logging.error(f"Error closing database connection: {e}")
            raise

# Test cases
def run_tests():
    import os

    # Test database file path
    test_db_path = 'test_containers.db'

    # Remove test database if it exists
    if os.path.exists(test_db_path):
        os.remove(test_db_path)

    # Initialize Persistence object
    persistence = Persistence(test_db_path)

    # Test valid data insertion
    try:
        valid_data = {
            'containerId': 'C123',
            'temperature': 25,
            'humidity': 60,
            'geo': {
                'latitude': 37.7749,
                'longitude': -122.4194
            },
            'timestamp': '2023-10-01T12:00:00Z'
        }
        persistence.insert(valid_data)
        print("Valid data insertion test passed.")
    except Exception as e:
        print(f"Valid data insertion test failed: {e}")

    # Test invalid data insertion (missing keys)
    try:
        invalid_data_missing_keys = {
            'containerId': 'C124',
            'temperature': 25,
            'humidity': 60,
            'timestamp': '2023-10-01T12:00:00Z'
        }
        persistence.insert(invalid_data_missing_keys)
        print("Invalid data insertion (missing keys) test failed.")
    except ValueError:
        print("Invalid data insertion (missing keys) test passed.")

    # Test invalid data insertion (wrong types)
    try:
        invalid_data_wrong_types = {
            'containerId': 123,  # Should be a string
            'temperature': '25',  # Should be an integer
            'humidity': 60,
            'geo': {
                'latitude': '37.7749',  # Should be a float
                'longitude': -122.4194
            },
            'timestamp': '2023-10-01T12:00:00Z'
        }
        persistence.insert(invalid_data_wrong_types)
        print("Invalid data insertion (wrong types) test failed.")
    except ValueError:
        print("Invalid data insertion (wrong types) test passed.")

    # Test database connection error handling
    try:
        persistence.close()
        persistence.insert(valid_data)  # Attempt to insert after closing connection
        print("Database connection error handling test failed.")
    except sqlite3.Error:
        print("Database connection error handling test passed.")

    # Clean up
    persistence.close()
    if os.path.exists(test_db_path):
        os.remove(test_db_path)

# Run tests
run_tests()
