```python
class AlbumService:
    def __init__(self):
        self.albums = []

    def add_record(self, title, artist, year, genre):
        # Validate input data types
        if not isinstance(title, str) or not isinstance(artist, str):
            raise ValueError("Title and artist must be strings.")
        if not isinstance(year, int) or year < 0:
            raise ValueError("Year must be a positive integer.")
        if not isinstance(genre, str):
            raise ValueError("Genre must be a string.")

        # Add album to the collection
        album = {
            'title': title,
            'artist': artist,
            'year': year,
            'genre': genre
        }
        self.albums.append(album)
        return "Album added successfully."

    def get_all_albums(self):
        return self.albums

    def search_by_option(self, option, value):
        if option not in ['title', 'artist', 'year', 'genre']:
            raise ValueError("Invalid search option.")

        # Perform search
        return [album for album in self.albums if str(album.get(option)).lower() == str(value).lower()]


def main():
    service = AlbumService()

    while True:
        print("\nMusic Album Management System")
        print("1. Add a new album to the collection")
        print("2. Get all albums in the collection")
        print("3. Search for an album")
        print("4. Quit the program")

