```python
from django.http import JsonResponse
from django.views.decorators.csrf import csrf_exempt
from django.utils.dateparse import parse_date
from AppCoder.models import Curso, Entregable
import json

@csrf_exempt
def curso(request):
    if request.method == 'POST':
        try:
            data = json.loads(request.body)
            nombre = data.get('nombre')
            camada = data.get('camada')

            if not nombre or not camada:
                return JsonResponse({'error': 'Missing required fields: nombre and camada'}, status=400)

            # Create and save the Curso object
            curso = Curso(nombre=nombre, camada=camada)
            curso.save()

            return JsonResponse({'success': True, 'curso': {'nombre': curso.nombre, 'camada': curso.camada}}, status=201)

        except json.JSONDecodeError:
            return JsonResponse({'error': 'Invalid JSON'}, status=400)
        except Exception as e:
            return JsonResponse({'error': str(e)}, status=500)

    return JsonResponse({'error': 'Invalid HTTP method'}, status=405)

@csrf_exempt
def entregables(request):
    if request.method == 'POST':
        try:
            data = json.loads(request.body)
            nombre = data.get('nombre')
            fecha_entrega_str = data.get('fechaEntrega')

            if not nombre or not fecha_entrega_str:
                return JsonResponse({'error': 'Missing required fields: nombre and fechaEntrega'}, status=400)

            fecha_entrega = parse_date(fecha_entrega_str)
            if not fecha_entrega:
                return JsonResponse({'error': 'Invalid date format'}, status=400)

            # Create and save the Entregable object
            entregable = Entregable(nombre=nombre, fechaEntrega=fecha_entrega)
            entregable.save()

            return JsonResponse({'success': True, 'entregable': {'nombre': entregable.nombre, 'fechaEntrega': entregable.fechaEntrega}}, status=201)

        except json.JSONDecodeError:
            return JsonResponse({'error': 'Invalid JSON'}, status=400)
        except Exception as e:
            return JsonResponse({'error': str(e)}, status=500)

    return JsonResponse({'error': 'Invalid HTTP method'}, status=405)
```

