                        value=ast.Name(id='fractions', ctx=ast.Load()),
                        attr='Fraction',
                        ctx=ast.Load()
                    ),
                    args=[node.left, node.right],
                    keywords=[]
                )
        return self.generic_visit(node)

    def visit_Name(self, node):
        # Automatic Symbol Definition
        if node.id not in self.defined_names and node.id not in dir(__builtins__):
            return ast.Call(
                func=ast.Attribute(
                    value=ast.Name(id='diofant', ctx=ast.Load()),
                    attr='Symbol',
                    ctx=ast.Load()
                ),
                args=[ast.Constant(value=node.id)],
                keywords=[]
            )
        return node

    def visit_Constant(self, node):
        # Float Rationalization
        if isinstance(node.value, float):
            return ast.Call(
                func=ast.Attribute(
                    value=ast.Name(id='fractions', ctx=ast.Load()),
                    attr='Fraction',
                    ctx=ast.Load()
                ),
                args=[ast.Constant(value=str(node.value))],
                keywords=[]
            )
        return node

    def visit_FunctionDef(self, node):
        # Unicode Identifiers Normalization
        node.name = self.normalize_identifier(node.name)
        node.args.args = [ast.arg(arg=self.normalize_identifier(arg.arg), annotation=arg.annotation) for arg in node.args.args]
        return self.generic_visit(node)

    def visit_ClassDef(self, node):
        # Unicode Identifiers Normalization
        node.name = self.normalize_identifier(node.name)
        return self.generic_visit(node)

    def normalize_identifier(self, identifier):
        return ''.join(
            c if c.isascii() else unicodedata.normalize('NFKD', c).encode('ascii', 'ignore').decode('ascii')
            for c in identifier
        )

def transform_code(code, defined_names):
    tree = ast.parse(code)
    transformer = CodeTransformer(defined_names)
    transformed_tree = transformer.visit(tree)
    return ast.unparse(transformed_tree)

