    def setUp(self):
        # Mock configuration for testing
        self.config = {
            'vmax': {
                'allocation_unit': 10  # Example allocation unit
            }
        }
        with open('vmax_config.yaml', 'w') as file:
            yaml.dump(self.config, file)

    def test_create_and_cleanup_vmax_volume(self):
        size_in_gb = 25
        volume_id = create_and_cleanup_vmax_volume(size_in_gb, self)
        self.assertTrue(volume_id.startswith("vol-"))

    def tearDown(self):
        # Clean up the mock configuration file
        import os
        os.remove('vmax_config.yaml')

if __name__ == '__main__':
    unittest.main()
