```python
class ScanManager:
    def __init__(self):
        self.scan_registry = {}

    def register_scan(self, scan_type, file_extensions):
        for ext in file_extensions:
            self.scan_registry[ext] = scan_type

    def execute_scan(self, file_path):
        # Extract the file extension
        file_extension = file_path.split('.')[-1]

        # Find the appropriate scan type
        scan_type = self.scan_registry.get(file_extension)

        if scan_type is None:
            raise ValueError(f"No scan type registered for file extension: .{file_extension}")

        # Execute the scan
        return scan_type().execute(file_path)


class BinaryScan:
    def execute(self, file_path):
        return f"BinaryScan executed for file: {file_path}"


class FileScan:
    def execute(self, file_path):
        return f"FileScan executed for file: {file_path}"


class JsonScan:
    def execute(self, file_path):
        return f"JsonScan executed for file: {file_path}"


class ArrowScan:
    def execute(self, file_path):
        return f"ArrowScan executed for file: {file_path}"


class DocScan:
    def execute(self, file_path):
        return f"DocScan executed for file: {file_path}"


class MaterializedScan:
    def execute(self, file_path):
        return f"MaterializedScan executed for file: {file_path}"


class PandasScan:
    def execute(self, file_path):
        return f"PandasScan executed for file: {file_path}"


# Example usage
scan_manager = ScanManager()
scan_manager.register_scan(BinaryScan, ['bin'])
scan_manager.register_scan(FileScan, ['txt', 'log'])
scan_manager.register_scan(JsonScan, ['json'])
scan_manager.register_scan(ArrowScan, ['arrow'])
scan_manager.register_scan(DocScan, ['docx', 'pdf'])
scan_manager.register_scan(MaterializedScan, [])
scan_manager.register_scan(PandasScan, ['csv'])

# Execute scans
