# motion_control.py

from drawpi.config import STEPS_MM

def steps_to_mm(steps):
    """Converts steps to millimeters using the STEPS_MM conversion factor."""
    if not isinstance(steps, (int, float)) or steps < 0:
        raise ValueError("Steps must be a non-negative number.")
    return steps / STEPS_MM

def mm_to_steps(mm):
    """Converts millimeters to steps, rounding to the nearest whole number."""
    if not isinstance(mm, (int, float)) or mm < 0:
        raise ValueError("Millimeters must be a non-negative number.")
    return round(mm * STEPS_MM)

def chunks(l, n):
    """Splits a list into chunks of size n."""
    if not isinstance(l, list) or not isinstance(n, int) or n <= 0:
        raise ValueError("Invalid input: l must be a list and n must be a positive integer.")
    for i in range(0, len(l), n):
        yield l[i:i + n]

def frequency_to_delay(frequency):
    """Converts frequency in Hertz to delay in microseconds."""
    if not isinstance(frequency, (int, float)) or frequency <= 0:
        raise ValueError("Frequency must be a positive number.")
    return 1_000_000 / frequency

def main():
    # Test steps_to_mm
    try:
        print("Steps to mm (100 steps):", steps_to_mm(100))
        print("Steps to mm (0 steps):", steps_to_mm(0))
    except ValueError as e:
        print("Error in steps_to_mm:", e)

    # Test mm_to_steps
    try:
        print("MM to steps (10 mm):", mm_to_steps(10))
        print("MM to steps (0 mm):", mm_to_steps(0))
    except ValueError as e:
        print("Error in mm_to_steps:", e)

    # Test chunks
    try:
        print("Chunks of [1, 2, 3, 4, 5] with size 2:", list(chunks([1, 2, 3, 4, 5], 2)))
        print("Chunks of [1, 2, 3, 4, 5] with size 3:", list(chunks([1, 2, 3, 4, 5], 3)))
    except ValueError as e:
        print("Error in chunks:", e)

    # Test frequency_to_delay
    try:
        print("Frequency to delay (1000 Hz):", frequency_to_delay(1000))
        print("Frequency to delay (500 Hz):", frequency_to_delay(500))
    except ValueError as e:
        print("Error in frequency_to_delay:", e)

if __name__ == "__main__":
    main()
```

