Below is a Python implementation of the "GemSwap" match-3 puzzle game using object-oriented programming principles. This implementation includes the main features you requested: grid setup, gem swapping, match detection, score tracking, and reshuffling when no moves are possible.

```python
import random

class Gem:
    COLORS = ['red', 'green', 'blue', 'yellow', 'purple', 'orange']

    def __init__(self):
        self.color = random.choice(Gem.COLORS)

    def __repr__(self):
        return self.color[0].upper()  # Represent gem by first letter of its color


class Grid:
    def __init__(self, size=8):
        self.size = size
        self.grid = [[Gem() for _ in range(size)] for _ in range(size)]
        self.score = 0

    def display(self):
        for row in self.grid:
            print(' '.join(str(gem) for gem in row))
        print(f"Score: {self.score}")

    def swap(self, x1, y1, x2, y2):
        if self.is_adjacent(x1, y1, x2, y2):
            self.grid[y1][x1], self.grid[y2][x2] = self.grid[y2][x2], self.grid[y1][x1]
            if self.find_matches():
                self.process_matches()
            else:
                # Swap back if no match is found
                self.grid[y1][x1], self.grid[y2][x2] = self.grid[y2][x2], self.grid[y1][x1]

    def is_adjacent(self, x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2) == 1

    def find_matches(self):
        matches = []
        # Check horizontal matches
        for y in range(self.size):
            for x in range(self.size - 2):
                if self.grid[y][x].color == self.grid[y][x + 1].color == self.grid[y][x + 2].color:
                    matches.append((x, y))
        # Check vertical matches
        for x in range(self.size):
            for y in range(self.size - 2):
                if self.grid[y][x].color == self.grid[y + 1][x].color == self.grid[y + 2][x].color:
                    matches.append((x, y))
        return matches

    def process_matches(self):
        matches = self.find_matches()
        if matches:
            for x, y in matches:
                self.grid[y][x] = None
                self.grid[y][x + 1] = None
                self.grid[y][x + 2] = None
                self.score += 3
            self.drop_gems()
            self.fill_empty_spaces()

    def drop_gems(self):
        for x in range(self.size):
            for y in range(self.size - 1, -1, -1):
                if self.grid[y][x] is None:
                    for k in range(y - 1, -1, -1):
                        if self.grid[k][x] is not None:
                            self.grid[y][x] = self.grid[k][x]
                            self.grid[k][x] = None
                            break

    def fill_empty_spaces(self):
        for y in range(self.size):
            for x in range(self.size):
                if self.grid[y][x] is None:
                    self.grid[y][x] = Gem()

    def reshuffle(self):
        flat_list = [gem for row in self.grid for gem in row]
        random.shuffle(flat_list)
        for y in range(self.size):
            for x in range(self.size):
                self.grid[y][x] = flat_list.pop()

    def has_possible_moves(self):
        for y in range(self.size):
            for x in range(self.size):
                if x < self.size - 1 and self.is_adjacent(x, y, x + 1, y):
                    self.swap(x, y, x + 1, y)
                    if self.find_matches():
                        self.swap(x, y, x + 1, y)  # Swap back
                        return True
                    self.swap(x, y, x + 1, y)  # Swap back
                if y < self.size - 1 and self.is_adjacent(x, y, x, y + 1):
                    self.swap(x, y, x, y + 1)
                    if self.find_matches():
                        self.swap(x, y, x, y + 1)  # Swap back
                        return True
                    self.swap(x, y, x, y + 1)  # Swap back
        return False

    def play(self):
        while True:
            self.display()
            if not self.has_possible_moves():
                print("No more possible moves, reshuffling...")
                self.reshuffle()
            try:
                x1, y1, x2, y2 = map(int, input("Enter swap coordinates (x1 y1 x2 y2): ").split())
                self.swap(x1, y1, x2, y2)
            except ValueError:
                print("Invalid input, please enter four integers separated by spaces.")

if __name__ == "__main__":
    game = Grid()
    game.play()
```

### Explanation:
- **Gem Class**: Represents individual gems with a random color chosen from a predefined list.
- **Grid Class**: Manages the 8x8 grid of gems, handles swapping, match detection, score tracking, and reshuffling.
- **Display Method**: Prints the current state of the grid and the player's score.
- **Swap Method**: Swaps two adjacent gems and checks for matches. If no match is found, it swaps them back.
- **Find Matches Method**: Detects horizontal and vertical matches of three or more gems.
- **Process Matches Method**: Removes matched gems, updates the score, and refills the grid.
- **Drop Gems Method**: Moves gems down to fill empty spaces.
- **Fill Empty Spaces Method**: Fills any remaining empty spaces with new gems.
- **Reshuffle Method**: Randomizes the grid when no moves are possible.
- **Has Possible Moves Method**: Checks if there are any valid moves left.
- **Play Method**: Main game loop allowing user interaction.

This implementation provides a basic structure for the game, allowing for further enhancements and features as needed.

