To create a Python program that automates the downloading of puzzle input data for the Advent of Code event, we need to follow the requirements you've outlined. Below is a complete implementation that meets these requirements:

```python
import os
import requests
import json
import sys
from datetime import datetime

def load_session_cookie():
    try:
        with open('.adventofcode.json', 'r') as f:
            data = json.load(f)
            return data.get('session')
    except FileNotFoundError:
        print("Error: .adventofcode.json file not found.")
        sys.exit(1)
    except json.JSONDecodeError:
        print("Error: .adventofcode.json file is not a valid JSON.")
        sys.exit(1)

def download_input(year, day, session_cookie):
    url = f"https://adventofcode.com/{year}/day/{day}/input"
    headers = {'Cookie': f'session={session_cookie}'}
    response = requests.get(url, headers=headers)

    if response.status_code == 200:
        return response.text
    else:
        print(f"Failed to download input for {year} day {day}: HTTP {response.status_code}")
        return None

def save_input(year, day, input_data):
    directory = f"{year}/{day}"
    os.makedirs(directory, exist_ok=True)
    file_path = os.path.join(directory, "input.txt")

    if not os.path.exists(file_path):
        with open(file_path, 'w') as f:
            f.write(input_data)
        print(f"Input for {year} day {day} saved to {file_path}.")
    else:
        print(f"Input for {year} day {day} already exists. Skipping download.")

def main():
    session_cookie = load_session_cookie()

    if len(sys.argv) > 1:
        try:
            year = int(sys.argv[1])
        except ValueError:
            print("Error: Year must be an integer.")
            sys.exit(1)
    else:
        year = datetime.now().year

    for day in range(1, 26):
        input_data = download_input(year, day, session_cookie)
        if input_data:
            save_input(year, day, input_data)

if __name__ == "__main__":
    main()
```

