Here's a Python class `IoTCoreLoRaWAN` that simulates managing AWS IoT Core for LoRaWAN resources using an in-memory database. This class provides methods to create, delete, associate, disassociate, and retrieve information about wireless devices, ensuring input validation and error handling.

```python
class IoTCoreLoRaWAN:
    def __init__(self):
        # In-memory database for storing devices and associations
        self.devices = {}
        self.device_profiles = {'profile1': {}, 'profile2': {}}  # Example profiles
        self.associations = {}

    def create_wireless_device(self, name: str, device_profile_id: str) -> dict:
        if not name or not device_profile_id:
            return {"error": "Invalid input: name and device_profile_id are required."}

        if device_profile_id not in self.device_profiles:
            return {"error": "Invalid device profile ID."}

        device_id = f"device_{len(self.devices) + 1}"
        device_details = {
            "device_id": device_id,
            "name": name,
            "device_profile_id": device_profile_id
        }
        self.devices[device_id] = device_details
        return device_details

    def delete_wireless_device(self, device_id: str) -> bool:
        if device_id not in self.devices:
            print("Error: Device ID not found.")
            return False

        if device_id in self.associations:
            print("Error: Device is associated with a thing. Disassociate before deleting.")
            return False

        del self.devices[device_id]
        return True

    def associate_device_with_thing(self, device_id: str, thing_name: str) -> bool:
        if device_id not in self.devices:
            print("Error: Device ID not found.")
            return False

        if not thing_name:
            print("Error: Thing name is required.")
            return False

        self.associations[device_id] = thing_name
        return True

    def disassociate_device_from_thing(self, device_id: str) -> bool:
        if device_id not in self.associations:
            print("Error: Device is not associated with any thing.")
            return False

        del self.associations[device_id]
        return True

    def get_wireless_device(self, device_id: str) -> dict:
        if device_id not in self.devices:
            return {"error": "Device ID not found."}

        return self.devices[device_id]

# Example usage
iot_core = IoTCoreLoRaWAN()
print(iot_core.create_wireless_device("DeviceA", "profile1"))
print(iot_core.get_wireless_device("device_1"))
print(iot_core.associate_device_with_thing("device_1", "ThingA"))
print(iot_core.disassociate_device_from_thing("device_1"))
print(iot_core.delete_wireless_device("device_1"))
```

