        return {'type': 'Input', 'shape': self.shape}

    @classmethod
    def from_dict(cls, layer_dict):
        if 'shape' not in layer_dict:
            raise ValueError("Missing 'shape' in Input layer dictionary.")
        return cls(shape=layer_dict['shape'])

    def get_output_shape(self):
        return self.shape

    def get_output_size(self):
        return int(np.prod(self.shape))


class Convolution(Layer):
    def __init__(self, input_shape, num_filters, kernel_size, stride=1, padding=0):
        self.input_shape = input_shape
        self.num_filters = num_filters
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

    def to_dict(self):
        return {
            'type': 'Convolution',
            'input_shape': self.input_shape,
            'num_filters': self.num_filters,
            'kernel_size': self.kernel_size,
            'stride': self.stride,
            'padding': self.padding
        }

    @classmethod
    def from_dict(cls, layer_dict):
        required_keys = ['input_shape', 'num_filters', 'kernel_size']
        for key in required_keys:
            if key not in layer_dict:
                raise ValueError(f"Missing '{key}' in Convolution layer dictionary.")
        return cls(
            input_shape=layer_dict['input_shape'],
            num_filters=layer_dict['num_filters'],
            kernel_size=layer_dict['kernel_size'],
            stride=layer_dict.get('stride', 1),
            padding=layer_dict.get('padding', 0)
        )

    def get_output_shape(self):
        h, w, _ = self.input_shape
        h_out = (h - self.kernel_size + 2 * self.padding) // self.stride + 1
        w_out = (w - self.kernel_size + 2 * self.padding) // self.stride + 1
        return (h_out, w_out, self.num_filters)

    def get_output_size(self):
        return int(np.prod(self.get_output_shape()))


class Pooling(Layer):
    def __init__(self, input_shape, pool_size, stride=1, padding=0):
        self.input_shape = input_shape
        self.pool_size = pool_size
        self.stride = stride
        self.padding = padding

    def to_dict(self):
        return {
            'type': 'Pooling',
            'input_shape': self.input_shape,
            'pool_size': self.pool_size,
            'stride': self.stride,
            'padding': self.padding
        }

    @classmethod
    def from_dict(cls, layer_dict):
        required_keys = ['input_shape', 'pool_size']
        for key in required_keys:
