            pool_size=layer_dict['pool_size'],
            stride=layer_dict.get('stride', 1),
            padding=layer_dict.get('padding', 0)
        )

    def get_output_shape(self):
        h, w, c = self.input_shape
        h_out = (h - self.pool_size + 2 * self.padding) // self.stride + 1
        w_out = (w - self.pool_size + 2 * self.padding) // self.stride + 1
        return (h_out, w_out, c)

    def get_output_size(self):
        return int(np.prod(self.get_output_shape()))


class FullConnection(Layer):
    def __init__(self, input_size, output_size):
        self.input_size = input_size
        self.output_size = output_size

    def to_dict(self):
        return {
            'type': 'FullConnection',
            'input_size': self.input_size,
            'output_size': self.output_size
        }

    @classmethod
    def from_dict(cls, layer_dict):
        required_keys = ['input_size', 'output_size']
        for key in required_keys:
            if key not in layer_dict:
                raise ValueError(f"Missing '{key}' in FullConnection layer dictionary.")
        return cls(
            input_size=layer_dict['input_size'],
            output_size=layer_dict['output_size']
        )

    def get_output_shape(self):
        return (self.output_size,)

    def get_output_size(self):
        return self.output_size


def from_dict(layer_dict):
    layer_type = layer_dict.get('type')
    if not layer_type:
