Here's an implementation of the `LaTeXDocument` class that meets the specified requirements. This class provides a high-level interface for generating LaTeX documents programmatically, with support for various elements and document metadata.

```python
import os
import subprocess

class LaTeXDocument:
    def __init__(self, filename, documentclass='article', options=None):
        self.filename = filename
        self.documentclass = documentclass
        self.options = options if options else []
        self.content = []
        self.packages = set()
        self.metadata = {'title': '', 'author': '', 'date': ''}
        self.indentation_level = 0

    def _escape_latex(self, text):
        special_chars = {
            '&': r'\&', '%': r'\%', '$': r'\$', '#': r'\#',
            '_': r'\_', '{': r'\{', '}': r'\}', '~': r'\textasciitilde{}',
            '^': r'\textasciicircum{}', '\\': r'\textbackslash{}'
        }
        for char, escape in special_chars.items():
            text = text.replace(char, escape)
        return text

    def _indent(self):
        return '    ' * self.indentation_level

    def _add_line(self, line):
        self.content.append(f"{self._indent()}{line}")

    def add_package(self, package):
        self.packages.add(package)

    def add_section(self, title, label=None):
        self._add_line(f"\\section{{{self._escape_latex(title)}}}")
        if label:
            self._add_line(f"\\label{{{label}}}")

    def add_subsection(self, title, label=None):
        self._add_line(f"\\subsection{{{self._escape_latex(title)}}}")
        if label:
            self._add_line(f"\\label{{{label}}}")

    def add_paragraph(self, text):
        self._add_line(self._escape_latex(text))
        self._add_line("")

    def add_bullet_points(self, items):
        self._add_line("\\begin{itemize}")
        self.indentation_level += 1
        for item in items:
            self._add_line(f"\\item {self._escape_latex(item)}")
        self.indentation_level -= 1
        self._add_line("\\end{itemize}")

    def add_equation(self, equation, label=None):
        self._add_line("\\begin{equation}")
        self.indentation_level += 1
        self._add_line(equation)
        if label:
            self._add_line(f"\\label{{{label}}}")
        self.indentation_level -= 1
        self._add_line("\\end{equation}")

    def add_image(self, filepath, options=None):
        options_str = f"[{options}]" if options else ""
        self._add_line(f"\\begin{figure}")
        self.indentation_level += 1
        self._add_line(f"\\includegraphics{options_str}{{{filepath}}}")
        self.indentation_level -= 1
        self._add_line("\\end{figure}")

    def add_table(self, data, column_format, caption=None, label=None):
        self._add_line(f"\\begin{table}")
        self.indentation_level += 1
        self._add_line(f"\\begin{tabular}{{{column_format}}}")
        self.indentation_level += 1
        for row in data:
            self._add_line(" & ".join(map(self._escape_latex, row)) + " \\\\")
        self.indentation_level -= 1
        self._add_line("\\end{tabular}")
        if caption:
            self._add_line(f"\\caption{{{self._escape_latex(caption)}}}")
        if label:
            self._add_line(f"\\label{{{label}}}")
        self.indentation_level -= 1
        self._add_line("\\end{table}")

    def set_metadata(self, title=None, author=None, date=None):
        if title:
            self.metadata['title'] = title
        if author:
            self.metadata['author'] = author
        if date:
            self.metadata['date'] = date

    def compile(self):
        header = [f"\\documentclass[{','.join(self.options)}]{{{self.documentclass}}}"]
        for package in self.packages:
            header.append(f"\\usepackage{{{package}}}")
        if self.metadata['title']:
            header.append(f"\\title{{{self._escape_latex(self.metadata['title'])}}}")
        if self.metadata['author']:
            header.append(f"\\author{{{self._escape_latex(self.metadata['author'])}}}")
        if self.metadata['date']:
            header.append(f"\\date{{{self._escape_latex(self.metadata['date'])}}}")
        else:
            header.append("\\date{}")

        header.append("\\begin{document}")
        if self.metadata['title']:
            header.append("\\maketitle")

        footer = ["\\end{document}"]

        with open(self.filename, 'w') as f:
            f.write("\n".join(header + self.content + footer))

        subprocess.run(['pdflatex', self.filename], check=True)

# Example usage:
