BOARD_SIZE = 5

def initialize_board():
    return [[EMPTY for _ in range(BOARD_SIZE)] for _ in range(BOARD_SIZE)]

def display_board(board):
    for row in board:
        print(' '.join(row))
    print()

def check_winner(board):
    # Check rows, columns, and diagonals for a winning line
    lines = []

    # Rows and columns
    for i in range(BOARD_SIZE):
        lines.append(board[i])  # Row
        lines.append([board[j][i] for j in range(BOARD_SIZE)])  # Column

    # Diagonals
    lines.append([board[i][i] for i in range(BOARD_SIZE)])
    lines.append([board[i][BOARD_SIZE - i - 1] for i in range(BOARD_SIZE)])

    for line in lines:
        if all(cell == PLAYER_O for cell in line):
            return PLAYER_O
        if all(cell == PLAYER_X for cell in line):
            return PLAYER_X

    return None

def is_valid_move(board, piece, target):
    x, y = piece
    tx, ty = target
    if board[x][y] == EMPTY or (tx, ty) == (x, y):
        return False
    if tx not in [0, BOARD_SIZE - 1] and ty not in [0, BOARD_SIZE - 1]:
        return False
    return True

def make_move(board, piece, target, player):
    x, y = piece
    tx, ty = target
    if is_valid_move(board, piece, target):
        board[tx][ty] = player
        board[x][y] = EMPTY
        return True
    return False

def human_move(board):
    while True:
        try:
            piece = tuple(map(int, input("Enter the piece position to move (row col): ").split()))
            target = tuple(map(int, input("Enter the target position (row col): ").split()))
            if make_move(board, piece, target, PLAYER_X):
                break
            else:
                print("Invalid move. Try again.")
        except ValueError:
            print("Invalid input. Please enter numbers for positions.")

def alpha_beta(board, depth, alpha, beta, maximizing_player):
    winner = check_winner(board)
    if winner == PLAYER_O:
        return 10
    elif winner == PLAYER_X:
        return -10
    elif all(board[i][j] != EMPTY for i in range(BOARD_SIZE) for j in range(BOARD_SIZE)):
        return 0

    if maximizing_player:
        max_eval = float('-inf')
        for i in range(BOARD_SIZE):
            for j in range(BOARD_SIZE):
                if board[i][j] == PLAYER_O or board[i][j] == EMPTY:
                    for tx in [0, BOARD_SIZE - 1]:
                        for ty in [0, BOARD_SIZE - 1]:
                            if make_move(board, (i, j), (tx, ty), PLAYER_O):
                                eval = alpha_beta(board, depth + 1, alpha, beta, False)
                                board[tx][ty] = EMPTY
                                board[i][j] = PLAYER_O
                                max_eval = max(max_eval, eval)
                                alpha = max(alpha, eval)
                                if beta <= alpha:
                                    break
        return max_eval
    else:
        min_eval = float('inf')
        for i in range(BOARD_SIZE):
            for j in range(BOARD_SIZE):
                if board[i][j] == PLAYER_X or board[i][j] == EMPTY:
                    for tx in [0, BOARD_SIZE - 1]:
                        for ty in [0, BOARD_SIZE - 1]:
                            if make_move(board, (i, j), (tx, ty), PLAYER_X):
                                eval = alpha_beta(board, depth + 1, alpha, beta, True)
                                board[tx][ty] = EMPTY
                                board[i][j] = PLAYER_X
                                min_eval = min(min_eval, eval)
                                beta = min(beta, eval)
                                if beta <= alpha:
                                    break
        return min_eval

def ai_move(board):
    best_score = float('-inf')
    best_move = None
    for i in range(BOARD_SIZE):
        for j in range(BOARD_SIZE):
            if board[i][j] == PLAYER_O or board[i][j] == EMPTY:
                for tx in [0, BOARD_SIZE - 1]:
                    for ty in [0, BOARD_SIZE - 1]:
                        if make_move(board, (i, j), (tx, ty), PLAYER_O):
                            score = alpha_beta(board, 0, float('-inf'), float('inf'), False)
                            board[tx][ty] = EMPTY
                            board[i][j] = PLAYER_O
                            if score > best_score:
                                best_score = score
                                best_move = ((i, j), (tx, ty))
    if best_move:
        make_move(board, best_move[0], best_move[1], PLAYER_O)

def play_game():
    board = initialize_board()
    display_board(board)
    while True:
        human_move(board)
        display_board(board)
        winner = check_winner(board)
        if winner:
            print(f"Player {winner} wins!")
            break
        ai_move(board)
        display_board(board)
        winner = check_winner(board)
        if winner:
            print(f"Player {winner} wins!")
            break
        if all(board[i][j] != EMPTY for i in range(BOARD_SIZE) for j in range(BOARD_SIZE)):
            print("It's a draw!")
            break

if __name__ == "__main__":
    play_game()
```

### Explanation:
- **Board Initialization**: The board is initialized as a 5x5 grid filled with empty spaces (`'.'`).
- **Display Board**: The board is printed after each move to provide visual feedback.
- **Check Winner**: The function checks rows, columns, and diagonals for a winning line.
- **Move Validation**: Ensures moves are valid by checking if the piece is on the edge and the target is empty or contains the player's token.
- **Human Move**: Allows the human player to input their move, with error handling for invalid inputs.
- **AI Move**: Uses the Alpha-Beta pruning algorithm to determine the best move for the AI player.
- **Game Loop**: Alternates between human and AI moves, checking for a winner or draw after each move.

This program provides a basic framework for playing Quixo with an AI opponent, ensuring optimal performance and robust error handling.

