class BaseModule:
    def _execute_initialization(self):
        logger.debug("BaseModule: Initialization started.")

    def _execute_start(self):
        logger.debug("BaseModule: Start process initiated.")

    def _execute_stop(self):
        logger.debug("BaseModule: Stop process initiated.")

class CustomModule(BaseModule):
