def read_integer(prompt):
    while True:
        try:
            value = int(input(prompt))
            return value
        except ValueError:
            print("Invalid input. Please enter an integer.")

def read_integer_pair(prompt):
    while True:
        try:
            pair = input(prompt).split()
            if len(pair) != 2:
                raise ValueError("Please enter exactly two integers.")
            a, b = map(int, pair)
            return a, b
        except ValueError:
            print("Invalid input. Please enter two integers separated by a space.")

def main():
    n = read_integer("Enter the number of pairs: ")

    for i in range(1, n + 1):
        a, b = read_integer_pair(f"Enter pair #{i} (two integers separated by space): ")
        sum_ab = a + b
        print(f"Case #{i}: {a} + {b} = {sum_ab}")

if __name__ == "__main__":
    main()
```

