```python
import datetime
from cryptography.fernet import Fernet

# Generate a key for encryption/decryption
# In a real-world scenario, this key should be securely stored and managed
encryption_key = Fernet.generate_key()
cipher = Fernet(encryption_key)

class UnsupportedDataTypeException(Exception):
    pass

class Secure:
    def __init__(self, value, encryption_level):
        self.encryption_level = encryption_level
        self.encrypted_value = self.encrypt(value)

    def encrypt(self, value):
        if isinstance(value, str):
            return cipher.encrypt(value.encode())
        elif isinstance(value, (int, float)):
            return cipher.encrypt(str(value).encode())
        elif isinstance(value, datetime.date):
            return cipher.encrypt(value.isoformat().encode())
        else:
            raise UnsupportedDataTypeException("Unsupported data type for encryption")

    def decrypt(self, access_level):
        if access_level >= self.encryption_level:
            return cipher.decrypt(self.encrypted_value).decode()
        else:
            raise PermissionError("Access level insufficient for decryption")

    def get_value(self, access_level):
        return self.decrypt(access_level)

class SecureString(Secure):
    def get_typed_value(self, access_level):
        return self.get_value(access_level)

class SecureDecimal(Secure):
    def get_typed_value(self, access_level):
        return float(self.get_value(access_level))

class SecureDate(Secure):
    def get_typed_value(self, access_level):
        return datetime.datetime.strptime(self.get_value(access_level), "%Y-%m-%d").date()

class SecureDateTime(Secure):
    def get_typed_value(self, access_level):
        return datetime.datetime.fromisoformat(self.get_value(access_level))

class SecureIncompleteDate(Secure):
    def get_typed_value(self, access_level):
        # Assuming incomplete date is in the format "YYYY-MM"
        return datetime.datetime.strptime(self.get_value(access_level), "%Y-%m")

# Unit tests
def test_secure_string():
    secure_string = SecureString("Hello, World!", encryption_level=1)
    assert secure_string.get_typed_value(access_level=1) == "Hello, World!"

def test_secure_decimal():
    secure_decimal = SecureDecimal(123.45, encryption_level=1)
    assert secure_decimal.get_typed_value(access_level=1) == 123.45

def test_secure_date():
    secure_date = SecureDate(datetime.date(2023, 10, 1), encryption_level=1)
    assert secure_date.get_typed_value(access_level=1) == datetime.date(2023, 10, 1)

def test_secure_datetime():
    secure_datetime = SecureDateTime(datetime.datetime(2023, 10, 1, 12, 0), encryption_level=1)
    assert secure_datetime.get_typed_value(access_level=1) == datetime.datetime(2023, 10, 1, 12, 0)

