To design a Python class-based system for managing task queues and task queue servers, we can create two main factory classes: `TaskQueueFactory` and `TaskQueueServerFactory`. These classes will handle the creation and configuration of task queues and servers, respectively. They will also ensure that necessary dependencies are installed and provide utilities for registering the created components. Additionally, the system will support environment variable overrides for consistent configuration across different environments.

Here's a possible implementation:

```python
import os
import importlib
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class TaskQueueFactory:
    def __init__(self, settings):
        self.settings = settings

    def validate_dependencies(self, queue_type):
        try:
            if queue_type == 'redis':
                importlib.import_module('redis')
            else:
                raise ValueError(f"Unsupported queue type: {queue_type}")
        except ImportError as e:
            logger.error(f"Required package for {queue_type} is not installed. Please install it.")
            raise

    def create_queue(self):
        queue_type = self.settings.get('queue_type', 'redis')
        self.validate_dependencies(queue_type)

        if queue_type == 'redis':
            return self.create_redis_queue()
        else:
            raise ValueError(f"Unsupported queue type: {queue_type}")

    def create_redis_queue(self):
        import redis
        host = os.getenv('REDIS_HOST', self.settings.get('host', 'localhost'))
        port = int(os.getenv('REDIS_PORT', self.settings.get('port', 6379)))
        password = os.getenv('REDIS_PASSWORD', self.settings.get('password', None))

        try:
            queue = redis.StrictRedis(host=host, port=port, password=password)
            logger.info("Redis queue created and registered successfully.")
            return queue
        except Exception as e:
            logger.error("Failed to create Redis queue. Please check your configuration.")
            raise

class TaskQueueServerFactory:
    def __init__(self, settings):
        self.settings = settings

    def validate_dependencies(self, server_type):
        try:
            if server_type == 'redis':
                importlib.import_module('redis')
            else:
                raise ValueError(f"Unsupported server type: {server_type}")
        except ImportError as e:
            logger.error(f"Required package for {server_type} is not installed. Please install it.")
            raise

    def create_server(self):
        server_type = self.settings.get('server_type', 'redis')
        self.validate_dependencies(server_type)

        if server_type == 'redis':
            return self.create_redis_server()
        else:
            raise ValueError(f"Unsupported server type: {server_type}")

    def create_redis_server(self):
        import redis
        host = os.getenv('REDIS_SERVER_HOST', self.settings.get('host', 'localhost'))
        port = int(os.getenv('REDIS_SERVER_PORT', self.settings.get('port', 6379)))
        password = os.getenv('REDIS_SERVER_PASSWORD', self.settings.get('password', None))

        try:
            server = redis.StrictRedis(host=host, port=port, password=password)
            logger.info("Redis server created and registered successfully.")
            return server
        except Exception as e:
            logger.error("Failed to create Redis server. Please check your configuration.")
            raise

# Example usage
queue_settings = {
    'queue_type': 'redis',
    'host': 'localhost',
    'port': 6379,
    'password': 'yourpassword'
}

server_settings = {
    'server_type': 'redis',
    'host': 'localhost',
    'port': 6379,
    'password': 'yourpassword'
}

queue_factory = TaskQueueFactory(queue_settings)
queue = queue_factory.create_queue()

server_factory = TaskQueueServerFactory(server_settings)
server = server_factory.create_server()
