class Plugin_v1:
    VERSION = "v1"
    CAPABILITY_IMPORT = False
    CAPABILITY_EXPORT = False

    def capabilities(self):
        return {
            "import": self.CAPABILITY_IMPORT,
            "export": self.CAPABILITY_EXPORT
        }

class Plugin_v2(Plugin_v1):
    VERSION = "v2"
    CAPABILITY_IMPORT = True
    CAPABILITY_EXPORT = True

    def capabilities(self):
        return {
            "import": self.CAPABILITY_IMPORT,
            "export": self.CAPABILITY_EXPORT
        }

class PluginManager:
    def __init__(self):
        self.plugins = {}

    def register_plugin(self, plugin):
        version = plugin.VERSION
        if version in self.plugins:
            raise ValueError(f"Plugin version '{version}' is already registered.")
        self.plugins[version] = plugin

    def get_plugin(self, version):
        if version not in self.plugins:
            raise KeyError(f"Plugin version '{version}' not found.")
        return self.plugins[version]

    def list_plugins(self):
        plugin_list = []
        for version, plugin in self.plugins.items():
            capabilities = plugin.capabilities()
            plugin_list.append({
                "version": version,
                "capabilities": capabilities
            })
        return plugin_list

# Example usage:
plugin_manager = PluginManager()

# Register plugins
